window.MUSCLE_QUESTIONS = [{"id":"h001","muscle":"Corrugator supercilii","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which small eyebrow muscle arises from the medial superciliary arch, inserts into eyebrow skin, and draws the eyebrows together?","options":["Corrugator supercilii","Procerus","Frontal belly of occipitofrontalis","Orbicularis oris","Risorius"],"answer":0,"note":"Corrugator supercilii draws the eyebrows medially, whereas the frontal belly of occipitofrontalis raises them.","source":{"volume":5,"pages":[16,19]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h002","muscle":"Orbicularis oculi","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which circular muscle surrounds the orbit and closes the eyelids?","options":["Orbicularis oculi","Levator palpebrae superioris","Superior rectus","Corrugator supercilii","Orbicularis oris"],"answer":0,"note":"Orbicularis oculi closes the eyelids during blinking, squinting, or forceful closure.","source":{"volume":5,"pages":[16,19]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h003","muscle":"Buccinator","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which cheek-wall muscle arises near the molar regions of both jaws and compresses the cheek against the teeth?","options":["Buccinator","Masseter","Risorius","Zygomaticus major","Orbicularis oris"],"answer":0,"note":"Buccinator compresses the cheek and blends with the muscles around the mouth.","source":{"volume":5,"pages":[19,24,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h004","muscle":"Risorius","region":"Head & neck","priority":"important","focus":"name","prompt":"Which slender muscle arises from fascia over the masseter and draws the corner of the mouth laterally?","options":["Risorius","Zygomaticus major","Depressor anguli oris","Mentalis","Levator labii superioris"],"answer":0,"note":"Risorius pulls the mouth corner sideways rather than lifting it toward the cheekbone.","source":{"volume":5,"pages":[24,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h005","muscle":"Temporalis","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which fan-shaped jaw-closing muscle passes deep to the zygomatic arch to reach the mandibular coronoid process?","options":["Temporalis","Masseter","Medial pterygoid","Lateral pterygoid","Buccinator"],"answer":0,"note":"Temporalis fills the temporal fossa and inserts on the coronoid process.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h006","muscle":"Masseter","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which jaw-closing muscle extends from the zygomatic arch to the lateral surface of the mandibular ramus and angle?","options":["Masseter","Medial pterygoid","Lateral pterygoid","Temporalis","Buccinator"],"answer":0,"note":"Masseter lies superficial to the lateral mandibular ramus and elevates the mandible.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h007","muscle":"Lateral pterygoid","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which muscle attaches to the mandibular neck and temporomandibular joint complex, helping protract the mandible and open the jaw?","options":["Lateral pterygoid","Medial pterygoid","Masseter","Temporalis","Mylohyoid"],"answer":0,"note":"Lateral pterygoid pulls the mandibular condyle forward and assists jaw opening.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h008","muscle":"Genioglossus","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which fan-shaped tongue muscle arises from the inner mandibular symphysis and is a major protruder of the tongue?","options":["Genioglossus","Geniohyoid","Hyoglossus","Styloglossus","Mylohyoid"],"answer":0,"note":"Genioglossus extends from the inner anterior mandible into the tongue.","source":{"volume":5,"pages":[33,34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h009","muscle":"Platysma","region":"Head & neck","priority":"important","focus":"name","prompt":"Which thin, superficial sheet extends from fascia over the upper chest to the mandible and skin of the lower face?","options":["Platysma","Sternocleidomastoid","Sternohyoid","Thyrohyoid","Trapezius"],"answer":0,"note":"Platysma is a superficial sheet associated with the skin of the lower face and neck.","source":{"volume":5,"pages":[35]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h010","muscle":"Sternocleidomastoid","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which muscle runs from the manubrium and medial clavicle to the mastoid process and turns the face to the opposite side?","options":["Sternocleidomastoid","Trapezius","Sternohyoid","Omohyoid","Anterior scalene"],"answer":0,"note":"A unilateral sternocleidomastoid contraction rotates the face away from the contracting side.","source":{"volume":5,"pages":[36]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h011","muscle":"Digastric","region":"Head & neck","priority":"standard","focus":"name","prompt":"Which muscle has anterior and posterior bellies joined by an intermediate tendon tethered to the hyoid, and can depress the mandible?","options":["Digastric","Omohyoid","Mylohyoid","Geniohyoid","Stylohyoid"],"answer":0,"note":"Digastric has two bellies linked by a tendon associated with the hyoid.","source":{"volume":5,"pages":[38,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h012","muscle":"Omohyoid","region":"Head & neck","priority":"standard","focus":"name","prompt":"Which two-bellied strap muscle runs from the scapula to the hyoid and helps depress the hyoid?","options":["Omohyoid","Digastric","Sternohyoid","Sternothyroid","Thyrohyoid"],"answer":0,"note":"Omohyoid links the scapular region to the hyoid through two bellies and an intermediate tendon.","source":{"volume":5,"pages":[40,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h013","muscle":"Longus colli","region":"Head & neck","priority":"standard","focus":"name","prompt":"Which prevertebral muscle spans the anterior cervical and upper thoracic vertebrae, reaches the atlas, and helps flex the neck?","options":["Longus colli","Longus capitis","Rectus capitis anterior","Anterior scalene","Sternocleidomastoid"],"answer":0,"note":"Longus colli attaches to anterior vertebral structures, including the atlas, and contributes to cervical flexion.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h014","muscle":"Superior oblique","region":"Head & neck","priority":"essential","focus":"name","prompt":"Which extraocular muscle changes direction through the trochlea before its tendon reaches the eyeball?","options":["Superior oblique","Inferior oblique","Superior rectus","Medial rectus","Levator palpebrae superioris"],"answer":0,"note":"The superior oblique tendon passes through the superomedial trochlea before turning toward the eyeball.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h015","muscle":"Posterior scalene","region":"Head & neck","priority":"standard","focus":"name","prompt":"Which scalene extends to the second rib, rather than the first rib, and can assist rib elevation?","options":["Posterior scalene","Anterior scalene","Middle scalene","Longus colli","Longus capitis"],"answer":0,"note":"Posterior scalene reaches the second rib; anterior and middle scalene reach the first.","source":{"volume":5,"pages":[42,43]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h016","muscle":"Occipitofrontalis","region":"Head & neck","priority":"essential","focus":"action","prompt":"With the epicranial aponeurosis fixed, what is the characteristic action of the frontal belly of occipitofrontalis?","options":["Elevate the eyebrows and wrinkle the forehead horizontally","Draw the eyebrows medially and inferiorly","Close the eyelids","Depress the lower lip","Compress the nostrils"],"answer":0,"note":"The frontal belly lifts the eyebrows and produces transverse forehead wrinkles.","source":{"volume":5,"pages":[17,19]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h017","muscle":"Occipitofrontalis","region":"Head & neck","priority":"important","focus":"action","prompt":"What is the characteristic action of the occipital belly of occipitofrontalis?","options":["Pull the scalp posteriorly","Depress the mandible","Elevate the upper eyelid","Draw the mouth corner downward","Compress the cheek against the teeth"],"answer":0,"note":"The occipital belly inserts into the epicranial aponeurosis and pulls the scalp backward.","source":{"volume":5,"pages":[17,19]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h018","muscle":"Nasalis","region":"Head & neck","priority":"standard","focus":"action","prompt":"What is the action of the alar part of nasalis?","options":["Dilate the nostril","Compress the nostril","Close the eyelids","Depress the lower lip","Retract the tongue"],"answer":0,"note":"The alar part dilates the nasal aperture, whereas the transverse part compresses it.","source":{"volume":5,"pages":[18]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h019","muscle":"Depressor labii inferioris","region":"Head & neck","priority":"important","focus":"action","prompt":"What is the principal action of depressor labii inferioris?","options":["Depress the lower lip","Elevate the upper lip","Retract the tongue","Elevate the mandible","Close the eyelids"],"answer":0,"note":"Depressor labii inferioris pulls the lower lip downward.","source":{"volume":5,"pages":[23,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h020","muscle":"Depressor anguli oris","region":"Head & neck","priority":"essential","focus":"action","prompt":"What does depressor anguli oris primarily do?","options":["Draw the corner of the mouth inferiorly","Raise the corner of the mouth toward the cheekbone","Protrude the tongue","Elevate the upper eyelid","Raise the eyebrows"],"answer":0,"note":"Depressor anguli oris lowers the mouth corner in expressions such as a frown.","source":{"volume":5,"pages":[23,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h021","muscle":"Mentalis","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which action best identifies mentalis?","options":["Elevate and wrinkle the skin of the chin","Elevate the upper lip and dilate the nostril","Close the eyelids","Retract the tongue","Elevate the mandibular ramus"],"answer":0,"note":"Mentalis inserts into chin skin and raises it, producing chin wrinkles.","source":{"volume":5,"pages":[23,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h022","muscle":"Orbicularis oris","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which action is characteristic of orbicularis oris?","options":["Close and purse the lips","Elevate the eyebrows","Open the eyelids","Depress the hyoid","Retract the tongue"],"answer":0,"note":"Orbicularis oris closes the oral opening and produces pursed or protruded lips.","source":{"volume":5,"pages":[19,23]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h023","muscle":"Levator labii superioris","region":"Head & neck","priority":"essential","focus":"action","prompt":"What is the principal action of levator labii superioris?","options":["Elevate the upper lip","Depress the lower lip","Close the eyelids","Pull the scalp posteriorly","Depress the hyoid"],"answer":0,"note":"Levator labii superioris pulls the upper lip upward.","source":{"volume":5,"pages":[22,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h024","muscle":"Zygomaticus major","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which movement is produced by zygomaticus major during smiling?","options":["Elevate the corner of the mouth superolaterally","Depress the corner of the mouth","Compress the nostrils","Retract the tongue","Elevate the upper eyelid"],"answer":0,"note":"Zygomaticus major draws the mouth corner upward toward the zygomatic bone.","source":{"volume":5,"pages":[22,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h025","muscle":"Medial rectus","region":"Head & neck","priority":"essential","focus":"action","prompt":"What is the principal action of medial rectus?","options":["Adduct the eyeball","Abduct the eyeball","Elevate the upper eyelid","Close the eyelids","Retract the eyeball"],"answer":0,"note":"Medial rectus turns the eyeball toward the nose.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h026","muscle":"Lateral rectus","region":"Head & neck","priority":"essential","focus":"action","prompt":"What is the principal action of lateral rectus?","options":["Abduct the eyeball","Adduct the eyeball","Elevate the upper eyelid","Close the eyelids","Protrude the eyeball"],"answer":0,"note":"Lateral rectus turns the eyeball away from the nose.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h027","muscle":"Superior rectus","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which vertical movement is produced by superior rectus?","options":["Elevation of the eyeball","Depression of the eyeball","Extorsion of the eyeball","Abduction of the eyeball","Retraction of the eyeball"],"answer":0,"note":"Superior rectus contributes to upward rotation of the eyeball.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h028","muscle":"Inferior rectus","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which vertical movement is produced by inferior rectus?","options":["Depression of the eyeball","Elevation of the eyeball","Intorsion of the eyeball","Abduction of the eyeball","Elevation of the upper eyelid"],"answer":0,"note":"Inferior rectus contributes to downward rotation of the eyeball.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h029","muscle":"Inferior oblique","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which rotational action is produced by inferior oblique?","options":["Extorsion: the superior pole of the eyeball rotates away from the nose","Intorsion: the superior pole of the eyeball rotates toward the nose","Adduction: the eyeball turns toward the nose","Depression: the eyeball turns downward","Elevation of the upper eyelid"],"answer":0,"note":"Inferior oblique produces extorsion of the eyeball; this differs from horizontal abduction.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h030","muscle":"Levator palpebrae superioris","region":"Head & neck","priority":"essential","focus":"action","prompt":"What is the principal action of levator palpebrae superioris?","options":["Elevate the upper eyelid","Close the eyelids","Elevate the eyeball","Adduct the eyeball","Compress the nostril"],"answer":0,"note":"Levator palpebrae superioris raises the upper eyelid rather than rotating the eyeball.","source":{"volume":5,"pages":[29]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h031","muscle":"Hyoglossus","region":"Head & neck","priority":"important","focus":"action","prompt":"What is the principal tongue movement produced by hyoglossus?","options":["Depress the tongue","Elevate the tongue","Protrude the tongue strongly","Close the lips","Elevate the mandible"],"answer":0,"note":"Hyoglossus pulls the tongue downward toward its hyoid attachment.","source":{"volume":5,"pages":[34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h032","muscle":"Styloglossus","region":"Head & neck","priority":"important","focus":"action","prompt":"Which combination describes the action of styloglossus?","options":["Retract and elevate the tongue","Protrude and depress the tongue","Depress the mandible and elevate the hyoid","Close the lips and compress the cheek","Depress the hyoid and larynx"],"answer":0,"note":"Styloglossus pulls the tongue backward and upward toward the styloid region.","source":{"volume":5,"pages":[34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h033","muscle":"Trapezius","region":"Head & neck","priority":"essential","focus":"action","prompt":"With its axial attachments fixed, what is a characteristic action of the descending upper part of trapezius?","options":["Elevate the scapula","Depress the hyoid","Protract the mandible","Depress the scapula","Flex the elbow"],"answer":0,"note":"The descending upper fibers of trapezius contribute to elevation of the scapula.","source":{"volume":5,"pages":[35]},"externalSources":[{"label":"UAMS · Back muscles","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"h034","muscle":"Thyrohyoid","region":"Head & neck","priority":"standard","focus":"action","prompt":"When the hyoid is fixed, which action can thyrohyoid produce?","options":["Elevate the larynx","Depress the larynx","Protrude the tongue","Elevate the mandible","Close the lips"],"answer":0,"note":"With the hyoid fixed, thyrohyoid pulls the thyroid cartilage and larynx upward.","source":{"volume":5,"pages":[40,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h035","muscle":"Geniohyoid","region":"Head & neck","priority":"standard","focus":"action","prompt":"With the mandible fixed, what does geniohyoid do to the hyoid?","options":["Elevate and protract it","Depress and retract it","Depress and protract it","Rotate it downward around the styloid process","Hold it posteriorly against the thyroid cartilage"],"answer":0,"note":"Geniohyoid pulls the hyoid upward and forward toward the mandibular symphysis.","source":{"volume":5,"pages":[41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"},{"label":"Complete Anatomy · Geniohyoid","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-neck/geniohyoid-muscle/21048"}]},{"id":"h036","muscle":"Procerus","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which bony landmark provides an origin for procerus?","options":["Nasal bone","Zygomatic arch","Mastoid process","Body of the hyoid","Coronoid process of the mandible"],"answer":0,"note":"Procerus arises over the nasal skeleton and extends to the skin between the eyebrows.","source":{"volume":5,"pages":[18]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h037","muscle":"Temporoparietalis","region":"Head & neck","priority":"standard","focus":"origin","prompt":"From which region does temporoparietalis arise in the lecture table?","options":["Fascia superior to the ear","Inner surface of the mandibular symphysis","Body and greater horn of the hyoid","Orbital surface of the maxilla","Posterior surface of the manubrium"],"answer":0,"note":"Temporoparietalis arises from fascia above the ear and reaches the lateral epicranial aponeurosis.","source":{"volume":5,"pages":[17]},"externalSources":[{"label":"Complete Anatomy · Temporoparietalis","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-head/temporoparietalis-muscle/20233"}]},{"id":"h038","muscle":"Medial pterygoid","region":"Head & neck","priority":"essential","focus":"origin","prompt":"Which surface contributes to the deep origin of medial pterygoid?","options":["Medial surface of the lateral pterygoid plate","Lateral surface of the lateral pterygoid plate","External surface of the mandibular angle","Coronoid process of the mandible","Anterior surface of the nasal bone"],"answer":0,"note":"The deep part of medial pterygoid arises from the medial surface of the lateral pterygoid plate.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h039","muscle":"Stylohyoid","region":"Head & neck","priority":"standard","focus":"origin","prompt":"What is the characteristic cranial origin of stylohyoid?","options":["Styloid process of the temporal bone","Zygomatic arch","Mastoid tip","Coronoid process of the mandible","Lesser wing of the sphenoid"],"answer":0,"note":"The name stylohyoid links its styloid origin to its hyoid insertion.","source":{"volume":5,"pages":[38,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h040","muscle":"Mylohyoid","region":"Head & neck","priority":"standard","focus":"origin","prompt":"From which mandibular region does mylohyoid arise?","options":["Mylohyoid line on the medial surface of the mandible","Lateral surface of the mandibular ramus","Mandibular condylar neck","Coronoid process","Mental skin below the mandible"],"answer":0,"note":"Mylohyoid arises from the inner mandible and forms much of the muscular floor of the mouth.","source":{"volume":5,"pages":[38,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h041","muscle":"Superior pharyngeal constrictor","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which attachment region is associated with superior pharyngeal constrictor?","options":["Medial pterygoid plate and adjacent pterygomandibular region","Greater horn of the hyoid as its main origin","Thyroid and cricoid cartilages as its main origin","Zygomatic arch","Superior border of the scapula"],"answer":0,"note":"The superior constrictor has upper pharyngeal attachments near the medial pterygoid and pterygomandibular region.","source":{"volume":5,"pages":[39,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h042","muscle":"Middle pharyngeal constrictor","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which structure provides the characteristic origin of middle pharyngeal constrictor?","options":["Hyoid bone","Zygomatic arch","Coronoid process","Mastoid process","Manubrium"],"answer":0,"note":"Middle pharyngeal constrictor fans posteriorly from the hyoid toward the pharyngeal raphe.","source":{"volume":5,"pages":[39,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h043","muscle":"Inferior pharyngeal constrictor","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which pair of structures provides the characteristic origin of inferior pharyngeal constrictor?","options":["Thyroid and cricoid cartilages","Hyoid body and greater horn","Zygomatic bone and zygomatic arch","Manubrium and medial clavicle","Nasal bone and frontal bone"],"answer":0,"note":"Inferior pharyngeal constrictor arises from laryngeal cartilages below the middle constrictor.","source":{"volume":5,"pages":[39,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h044","muscle":"Sternohyoid","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which attachment belongs to the origin of sternohyoid?","options":["Posterior manubrium and medial clavicular region","Superior border of the scapula","Styloid process","Inner mandibular symphysis","Thyroid cartilage"],"answer":0,"note":"Sternohyoid begins in the upper sternoclavicular region and ascends to the hyoid.","source":{"volume":5,"pages":[40,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h045","muscle":"Sternothyroid","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which structure provides the inferior origin of sternothyroid?","options":["Posterior surface of the manubrium","Inferior border of the hyoid","Superior border of the scapula","Mastoid process","Body of the mandible"],"answer":0,"note":"Sternothyroid runs from the posterior manubrium to the thyroid cartilage.","source":{"volume":5,"pages":[41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h046","muscle":"Anterior scalene","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which region provides the vertebral origin of anterior scalene?","options":["Cervical transverse processes","Cervical spinous processes","Thoracic spinous processes","Anterior surface of the sacrum","Mastoid process"],"answer":0,"note":"Anterior scalene descends from cervical transverse processes toward the first rib.","source":{"volume":5,"pages":[42,43]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h047","muscle":"Middle scalene","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which region provides the vertebral origin of middle scalene?","options":["Cervical transverse processes","Cervical spinous processes","Upper thoracic vertebral bodies","Occipital squama","Posterior surface of the manubrium"],"answer":0,"note":"Middle scalene descends from cervical transverse processes to the first rib.","source":{"volume":5,"pages":[42,43]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h048","muscle":"Levator labii superioris","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Where does levator labii superioris insert?","options":["Skin and muscle of the upper lip","Skin and muscle of the lower lip","Skin of the chin","Coronoid process of the mandible","Epicranial aponeurosis"],"answer":0,"note":"Its upper-lip insertion explains why levator labii superioris elevates that lip.","source":{"volume":5,"pages":[22,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h049","muscle":"Mentalis","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Where does mentalis insert?","options":["Skin of the chin","Skin of the upper lip","Epicranial aponeurosis","Hyoid body","Mandibular coronoid process"],"answer":0,"note":"Mentalis runs from the anterior mandible into chin skin, allowing it to wrinkle the chin.","source":{"volume":5,"pages":[23,26]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h050","muscle":"Corrugator supercilii","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Where does corrugator supercilii insert?","options":["Skin of the eyebrow","Skin of the chin","Skin of the mouth corner","Superior tarsal plate","Epicranial aponeurosis"],"answer":0,"note":"Corrugator inserts into eyebrow skin and draws it medially and inferiorly.","source":{"volume":5,"pages":[16,19]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h051","muscle":"Temporoparietalis","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Where does temporoparietalis insert according to the lecture?","options":["Lateral border of the epicranial aponeurosis","Medial surface of the mandibular angle","Superior tarsal plate","Hyoid body","Skin of the lower lip"],"answer":0,"note":"Temporoparietalis connects the supra-auricular fascia to the lateral epicranial aponeurosis.","source":{"volume":5,"pages":[17]},"externalSources":[{"label":"Complete Anatomy · Temporoparietalis","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-head/temporoparietalis-muscle/20233"}]},{"id":"h052","muscle":"Occipitofrontalis","region":"Head & neck","priority":"important","focus":"insertion","prompt":"Where does the occipital belly of occipitofrontalis insert?","options":["Epicranial aponeurosis","Skin of the upper lip","Superior tarsal plate","Mandibular ramus","Hyoid body"],"answer":0,"note":"The occipital belly attaches to the epicranial aponeurosis, whereas the frontal belly reaches eyebrow skin.","source":{"volume":5,"pages":[17,19]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h053","muscle":"Masseter","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Which attachment is an insertion of masseter?","options":["Lateral surface of the mandibular ramus and angle","Medial surface of the mandibular angle","Mandibular coronoid process as its principal insertion","Hyoid body","Skin of the upper lip"],"answer":0,"note":"Masseter inserts externally on the mandibular ramus and angle, opposite the medial pterygoid attachment.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h054","muscle":"Temporalis","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Which mandibular process receives the main tendon of temporalis?","options":["Coronoid process","Condylar process","Mental protuberance","Mandibular lingula","Digastric fossa"],"answer":0,"note":"Temporalis inserts on the coronoid process and adjacent anterior border of the ramus.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h055","muscle":"Lateral pterygoid","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Which attachment is associated with lateral pterygoid?","options":["Mandibular neck and the temporomandibular joint capsule or disc","Mandibular coronoid process","Lateral mandibular angle","Hyoid body and median raphe","Skin at the corner of the mouth"],"answer":0,"note":"Lateral pterygoid attaches to the mandibular neck, with upper-head fibers associated with the joint capsule and disc.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h056","muscle":"Styloglossus","region":"Head & neck","priority":"important","focus":"insertion","prompt":"Where does styloglossus insert?","options":["Lateral aspect of the tongue","Body of the hyoid","Skin of the chin","Superior tarsal plate","Thyroid cartilage"],"answer":0,"note":"Styloglossus travels from the styloid process into the lateral tongue.","source":{"volume":5,"pages":[34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h057","muscle":"Hyoglossus","region":"Head & neck","priority":"important","focus":"insertion","prompt":"Where does hyoglossus insert?","options":["Inferolateral aspect of the tongue","Mandibular coronoid process","Epicranial aponeurosis","Thyroid cartilage","Skin of the lower lip"],"answer":0,"note":"Hyoglossus reaches the inferolateral tongue from the hyoid body and greater horn.","source":{"volume":5,"pages":[34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h058","muscle":"Sternocleidomastoid","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Which temporal-bone landmark receives sternocleidomastoid?","options":["Mastoid process","Styloid process","Zygomatic process","Mandibular fossa","Petrous apex"],"answer":0,"note":"Sternocleidomastoid reaches the mastoid process from its sternal and clavicular origins.","source":{"volume":5,"pages":[36]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h059","muscle":"Mylohyoid","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Which pair describes the insertion of mylohyoid?","options":["Hyoid body and median mylohyoid raphe","Thyroid cartilage and cricoid cartilage","Mastoid process and superior nuchal line","Coronoid process and mandibular neck","Upper lip and mouth corner"],"answer":0,"note":"Mylohyoid fibers reach the midline raphe and hyoid, forming a muscular floor beneath the mouth.","source":{"volume":5,"pages":[38,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h060","muscle":"Sternothyroid","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Where does sternothyroid insert?","options":["Thyroid cartilage","Body of the hyoid","Mastoid process","Mandibular symphysis","Superior border of the scapula"],"answer":0,"note":"Sternothyroid ends on thyroid cartilage, unlike sternohyoid, which reaches the hyoid.","source":{"volume":5,"pages":[41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h061","muscle":"Zygomaticus minor","region":"Head & neck","priority":"important","focus":"insertion","prompt":"Unlike zygomaticus major, where does zygomaticus minor chiefly insert?","options":["Upper lip","Corner of the mouth","Lower lip","Skin of the chin","Mandibular angle"],"answer":0,"note":"Zygomaticus minor elevates the upper lip; zygomaticus major primarily elevates the mouth corner.","source":{"volume":5,"pages":[22,25]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}],"correction":{"text":"The PDF combines the two zygomaticus muscles; minor reaches the upper lip, whereas major reaches the mouth corner.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}},{"id":"h062","muscle":"Levator labii superioris alaeque nasi","region":"Head & neck","priority":"standard","focus":"action","prompt":"Which paired action is characteristic of levator labii superioris alaeque nasi?","options":["Elevate the upper lip and flare the nostril","Depress the lower lip and wrinkle the chin","Close the eyelids and raise the eyebrows","Depress the mouth corner and retract the scalp","Compress the nostril and depress the upper lip"],"answer":0,"note":"Its attachments to the nasal ala and upper lip allow it to lift the lip and widen the nostril.","source":{"volume":5,"pages":[15]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h063","muscle":"Tensor veli palatini","region":"Head & neck","priority":"standard","focus":"action","prompt":"What is a principal action of tensor veli palatini?","options":["Tense the soft palate and help open the auditory tube","Elevate the upper eyelid","Protrude the tongue","Depress the hyoid","Constrict the oral opening"],"answer":0,"note":"Tensor veli palatini tightens the soft palate and contributes to opening the auditory tube.","source":{"volume":5,"pages":[39]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h064","muscle":"Levator veli palatini","region":"Head & neck","priority":"standard","focus":"action","prompt":"Which action best describes levator veli palatini?","options":["Elevate the soft palate","Depress the larynx","Protract the mandible","Depress the sides of the tongue","Close the lips"],"answer":0,"note":"Levator veli palatini lifts the soft palate toward the posterior pharyngeal wall.","source":{"volume":5,"pages":[39]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h065","muscle":"Rectus capitis anterior","region":"Head & neck","priority":"standard","focus":"action","prompt":"Which head movement is produced by rectus capitis anterior?","options":["Flexion at the upper cervical region","Extension at the upper cervical region","Elevation of the scapula","Depression of the hyoid","Protraction of the mandible"],"answer":0,"note":"Rectus capitis anterior lies in front of the atlanto-occipital region and contributes to head flexion.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h066","muscle":"Rectus capitis lateralis","region":"Head & neck","priority":"standard","focus":"action","prompt":"What movement is produced by unilateral rectus capitis lateralis?","options":["Lateral bending of the head toward the contracting side","Turning the chin away while depressing the mandible","Elevation of the first rib","Depression of the hyoid","Protraction of the tongue"],"answer":0,"note":"Rectus capitis lateralis connects the atlas to the occipital bone and assists ipsilateral lateral bending.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h067","muscle":"Longus capitis","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Which cranial region receives longus capitis?","options":["Basilar portion of the occipital bone","Mastoid process of the temporal bone","Styloid process of the temporal bone","Mandibular coronoid process","Zygomatic arch"],"answer":0,"note":"Longus capitis ascends from cervical transverse processes to the occipital base.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h068","muscle":"Superior oblique","region":"Head & neck","priority":"essential","focus":"origin","prompt":"Where does superior oblique originate before running forward to the trochlea?","options":["Body of the sphenoid, superomedial to the optic canal","Common tendinous ring","Anterior orbital surface of the maxilla","Superior tarsal plate","Lateral orbital rim of the zygomatic bone"],"answer":0,"note":"Superior oblique begins on the sphenoid body and then approaches the trochlea along the superomedial orbit.","source":{"volume":5,"pages":[28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"},{"label":"Complete Anatomy · Superior oblique","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-head/superior-oblique-muscle/22893"}],"correction":{"text":"PDF p.28 incorrectly groups superior oblique with the common tendinous ring; its origin is on the sphenoid body.","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-head/superior-oblique-muscle/22893"}},{"id":"h069","muscle":"Inferior oblique","region":"Head & neck","priority":"essential","focus":"origin","prompt":"Which site provides the origin of inferior oblique?","options":["Anterior orbital floor on the maxilla, lateral to the lacrimal groove","Common tendinous ring at the orbital apex","Superior tarsal plate","Body of the sphenoid above the optic canal","Medial eyebrow skin"],"answer":0,"note":"Inferior oblique uniquely starts anteriorly on the orbital floor rather than at the orbital apex.","source":{"volume":5,"pages":[28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"},{"label":"Complete Anatomy · Inferior oblique","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-head/inferior-oblique-muscle/21654"}]},{"id":"h070","muscle":"Medial rectus","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Where does medial rectus insert?","options":["Sclera on the medial surface of the eyeball","Sclera on the lateral surface of the eyeball","Superior tarsal plate","Inferior tarsal plate","Medial palpebral ligament"],"answer":0,"note":"Medial rectus attaches to the medial sclera and pulls the eyeball toward the nose.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h071","muscle":"Lateral rectus","region":"Head & neck","priority":"essential","focus":"origin","prompt":"Which structure provides the origin of lateral rectus?","options":["Common tendinous ring at the orbital apex","Anterior orbital floor of the maxilla","Superior tarsal plate","Medial eyebrow skin","Trochlea in the anterior superomedial orbit"],"answer":0,"note":"Lateral rectus shares the common tendinous ring with the other three rectus muscles.","source":{"volume":5,"pages":[28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h072","muscle":"Superior rectus","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Which structure receives the superior rectus tendon?","options":["Sclera on the superior surface of the eyeball","Superior tarsal plate","Inferior tarsal plate","Skin of the eyebrow","Medial palpebral ligament"],"answer":0,"note":"Superior rectus inserts on the globe, whereas levator palpebrae superioris reaches the upper eyelid.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h073","muscle":"Inferior rectus","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Which structure receives inferior rectus?","options":["Sclera on the inferior surface of the eyeball","Inferior tarsal plate","Superior tarsal plate","Orbicularis oculi around the lower eyelid","Anterior lacrimal crest"],"answer":0,"note":"Inferior rectus attaches to the inferior sclera and contributes to downward movement of the globe.","source":{"volume":5,"pages":[27,28]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h074","muscle":"Levator palpebrae superioris","region":"Head & neck","priority":"essential","focus":"origin","prompt":"Where is the origin of levator palpebrae superioris?","options":["Lesser wing of the sphenoid above the optic canal","Anterior orbital floor of the maxilla","Inferior orbital rim","Superior tarsal plate","Zygomatic arch"],"answer":0,"note":"Levator palpebrae superioris begins above the optic canal and runs forward to the upper eyelid.","source":{"volume":5,"pages":[29]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"},{"label":"Complete Anatomy · Levator palpebrae superioris","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-head/levator-palpebrae-superioris/23949"}]},{"id":"h075","muscle":"Temporalis","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which additional action is especially associated with the posterior fibers of temporalis?","options":["Retract the mandible","Protract the mandible","Depress the hyoid","Protrude the tongue","Open the eyelids"],"answer":0,"note":"The posterior temporal fibers pull the mandible backward, while the muscle as a whole helps elevate it.","source":{"volume":5,"pages":[32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h076","muscle":"Medial pterygoid","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Where does medial pterygoid insert relative to the mandibular angle?","options":["Medial surface of the angle and ramus","Lateral surface of the angle and ramus","Coronoid process only","Anterior mandibular symphysis","Articular disc of the temporomandibular joint"],"answer":0,"note":"Medial pterygoid attaches internally near the mandibular angle, opposite the external masseter attachment.","source":{"volume":5,"pages":[30,32]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h077","muscle":"Lateral pterygoid","region":"Head & neck","priority":"essential","focus":"origin","prompt":"Which surface provides the origin of the inferior head of lateral pterygoid?","options":["Lateral surface of the lateral pterygoid plate","Medial surface of the lateral pterygoid plate","Pyramidal process of the palatine bone","Maxillary tuberosity","Medial surface of the mandibular angle"],"answer":0,"note":"The inferior head starts on the outer face of the lateral pterygoid plate; the superior head starts on the sphenoid greater wing.","source":{"volume":5,"pages":[30]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}],"correction":{"text":"The PDF adds palatine bone to lateral pterygoid; the standard inferior-head origin is the lateral surface of the lateral pterygoid plate.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}},{"id":"h078","muscle":"Genioglossus","region":"Head & neck","priority":"essential","focus":"insertion","prompt":"Which description best captures the broad insertion of genioglossus?","options":["Fibers fan into the tongue from near its tip toward its base","A narrow tendon ends on the mandibular coronoid process","Fibers end only on the upper lip","A tendon ends on the mastoid process","Fibers form the posterior pharyngeal raphe only"],"answer":0,"note":"Genioglossus spreads through the tongue rather than ending as a single narrow cranial tendon.","source":{"volume":5,"pages":[34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h079","muscle":"Styloglossus","region":"Head & neck","priority":"important","focus":"origin","prompt":"What is the characteristic origin of styloglossus?","options":["Styloid process of the temporal bone","Body of the hyoid","Inner mandibular symphysis","Greater horn of the hyoid","Thyroid cartilage"],"answer":0,"note":"Styloglossus runs from the temporal styloid process toward the posterolateral tongue.","source":{"volume":5,"pages":[34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h080","muscle":"Hyoglossus","region":"Head & neck","priority":"important","focus":"origin","prompt":"Which pair provides the main origin of hyoglossus?","options":["Body and greater horn of the hyoid","Mandibular symphysis and coronoid process","Styloid and mastoid processes","Thyroid and cricoid cartilages","Hard palate and upper lip"],"answer":0,"note":"Hyoglossus begins on the hyoid and spreads into the sides of the tongue.","source":{"volume":5,"pages":[34]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h081","muscle":"Stylohyoid","region":"Head & neck","priority":"standard","focus":"action","prompt":"With the mandible at rest, which hyoid movement is characteristic of stylohyoid?","options":["Elevation and retraction","Depression and protraction","Depression and retraction","Protraction without elevation","Lateral rotation toward the mandibular condyle"],"answer":0,"note":"Stylohyoid pulls the hyoid upward and backward toward the styloid process.","source":{"volume":5,"pages":[41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h082","muscle":"Digastric","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Where does the anterior belly of digastric originate?","options":["Digastric fossa of the mandible","Mastoid notch of the temporal bone","Styloid process of the temporal bone","Superior border of the scapula","Thyroid cartilage"],"answer":0,"note":"The anterior belly begins at the mandibular digastric fossa; the posterior belly begins at the mastoid notch.","source":{"volume":5,"pages":[38,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h083","muscle":"Digastric","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which precise temporal-bone landmark gives origin to the posterior belly of digastric?","options":["Mastoid notch","Styloid process","Zygomatic process","Mandibular fossa","Petrous apex"],"answer":0,"note":"The posterior belly arises from the mastoid notch, medial to the mastoid process.","source":{"volume":5,"pages":[38,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}],"correction":{"text":"The PDF uses the broader term mastoid process; mastoid notch is the precise origin of the posterior belly.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}},{"id":"h084","muscle":"Geniohyoid","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Where does geniohyoid insert?","options":["Body of the hyoid","Thyroid cartilage","Mastoid process","Skin of the chin","Posterior pharyngeal raphe"],"answer":0,"note":"Geniohyoid connects the mandibular mental spine region to the hyoid body.","source":{"volume":5,"pages":[41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h085","muscle":"Thyrohyoid","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which structure provides the origin of thyrohyoid?","options":["Oblique line of the thyroid cartilage","Posterior surface of the manubrium","Superior border of the scapula","Mandibular digastric fossa","Styloid process"],"answer":0,"note":"Thyrohyoid spans the short distance between thyroid cartilage and the hyoid.","source":{"volume":5,"pages":[40,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h086","muscle":"Thyrohyoid","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Which structure receives thyrohyoid superiorly?","options":["Lower border of the hyoid bone","Posterior pharyngeal raphe","Mandibular coronoid process","Mastoid process","Superior border of the scapula"],"answer":0,"note":"Thyrohyoid joins thyroid cartilage to the lower hyoid, allowing either structure to move depending on fixation.","source":{"volume":5,"pages":[40,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h087","muscle":"Middle pharyngeal constrictor","region":"Head & neck","priority":"standard","focus":"action","prompt":"What is the main swallowing action of middle pharyngeal constrictor?","options":["Narrow the pharyngeal cavity to help advance the food bolus","Protrude the tongue through the lips","Pull the mandibular condyle forward","Open the oral aperture by depressing the mandible","Close the eyelids"],"answer":0,"note":"Middle pharyngeal constrictor participates in the sequential narrowing that moves food through the pharynx.","source":{"volume":5,"pages":[39,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h088","muscle":"Superior pharyngeal constrictor","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Which posterior structure receives fibers of superior pharyngeal constrictor?","options":["Midline pharyngeal raphe","Median mylohyoid raphe","Pterygomandibular raphe as the posterior insertion","Superior tarsal plate","Epicranial aponeurosis"],"answer":0,"note":"Superior pharyngeal constrictor reaches the posterior pharyngeal raphe and superiorly the pharyngeal tubercle.","source":{"volume":5,"pages":[39,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h089","muscle":"Omohyoid","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"What is the superior insertion of the omohyoid muscle?","options":["Lower border of the hyoid bone","Oblique line of the thyroid cartilage","Mastoid process","Mandibular coronoid process","Zygomatic arch"],"answer":0,"note":"The superior belly of omohyoid reaches the lower hyoid; its inferior belly begins on the scapula.","source":{"volume":5,"pages":[40,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h090","muscle":"Sternohyoid","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Where does sternohyoid insert superiorly?","options":["Lower border of the hyoid bone","Oblique line of the thyroid cartilage","Mastoid process","Body of the mandible","Superior border of the scapula"],"answer":0,"note":"Sternohyoid reaches the hyoid, whereas the deeper sternothyroid stops at thyroid cartilage.","source":{"volume":5,"pages":[40,41]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h091","muscle":"Anterior scalene","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Which rib landmark receives anterior scalene?","options":["Scalene tubercle of the first rib","Lateral surface of the second rib","Inferior margin of the twelfth rib","Costal cartilage of the fifth rib","Clavicular conoid tubercle"],"answer":0,"note":"Anterior scalene descends to the scalene tubercle on the first rib.","source":{"volume":5,"pages":[42,43]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h092","muscle":"Middle scalene","region":"Head & neck","priority":"standard","focus":"action","prompt":"With its cervical attachments fixed, which respiratory action can middle scalene produce?","options":["Elevate the first rib","Depress the first rib","Elevate the second rib without affecting the first","Depress the hyoid","Elevate the scapula"],"answer":0,"note":"Middle scalene attaches to the first rib and can lift it during inspiration.","source":{"volume":5,"pages":[42,43]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h093","muscle":"Posterior scalene","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which vertebral structures give origin to posterior scalene?","options":["Posterior tubercles of lower cervical transverse processes","Posterior tubercle of the atlas alone","Spinous process of the axis alone","Upper thoracic vertebral bodies","Anterior sacral surface"],"answer":0,"note":"Posterior scalene descends from lower cervical transverse processes to the second rib.","source":{"volume":5,"pages":[42,43]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h094","muscle":"Longus colli","region":"Head & neck","priority":"standard","focus":"action","prompt":"What is a principal movement produced by bilateral longus colli contraction?","options":["Flexion of the neck","Extension of the neck","Elevation of the scapula","Depression of the mandible","Retraction of the tongue"],"answer":0,"note":"Longus colli lies on the front of the cervical vertebral column and contributes to neck flexion.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h095","muscle":"Longus capitis","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which region gives origin to longus capitis?","options":["Anterior tubercles of C3-C6 transverse processes","Spinous processes of C7-T12","Posterior surface of the manubrium","Superior border of the scapula","Mastoid process"],"answer":0,"note":"Longus capitis ascends from mid-cervical transverse processes to the basilar occipital bone.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h096","muscle":"Rectus capitis anterior","region":"Head & neck","priority":"standard","focus":"origin","prompt":"Which atlas region provides an origin for rectus capitis anterior?","options":["Anterior aspect of the lateral mass","Posterior tubercle","Posterior arch behind the vertebral artery groove","Spinous process of the axis","Dens of the axis"],"answer":0,"note":"Rectus capitis anterior is a short prevertebral muscle joining the atlas lateral mass to the occipital base.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h097","muscle":"Rectus capitis lateralis","region":"Head & neck","priority":"standard","focus":"insertion","prompt":"Where does rectus capitis lateralis insert?","options":["Occipital bone anterolateral to the foramen magnum","Anterior arch of the atlas","Mastoid process","Body of the axis","First rib"],"answer":0,"note":"Rectus capitis lateralis joins the atlas transverse process to the lateral occipital base.","source":{"volume":5,"pages":[42]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h098","muscle":"Sternocleidomastoid","region":"Head & neck","priority":"essential","focus":"action","prompt":"Which movement of the face is expected when the right sternocleidomastoid contracts alone?","options":["Turn the face to the left","Turn the face to the right","Open the mandible without moving the head","Retract the tongue","Elevate the left upper eyelid"],"answer":0,"note":"Right sternocleidomastoid rotates the chin toward the opposite side while also contributing to right lateral neck bending.","source":{"volume":5,"pages":[36]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h099","muscle":"Platysma","region":"Head & neck","priority":"important","focus":"origin","prompt":"Which region provides the lower origin of platysma?","options":["Fascia over pectoralis major and deltoid","Deep surface of the hyoid body","Oblique line of the thyroid cartilage","Anterior tubercles of cervical transverse processes","Posterior surface of the mastoid process"],"answer":0,"note":"Platysma begins in superficial upper chest fascia and ascends toward the mandible and lower facial skin.","source":{"volume":5,"pages":[35]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"h100","muscle":"Nasalis","region":"Head & neck","priority":"standard","focus":"action","prompt":"Which action is associated with the transverse part of nasalis?","options":["Compress or flatten the nasal aperture","Flare the nostril","Elevate the upper eyelid","Elevate the tongue","Depress the mandible"],"answer":0,"note":"The transverse part compresses the nasal region, whereas the alar part flares the nostril.","source":{"volume":5,"pages":[18]},"externalSources":[{"label":"UAMS · Head & neck","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-head-and-neck/"}]},{"id":"u001","muscle":"Iliocostalis","region":"Trunk","priority":"important","focus":"name","prompt":"Which muscle group forms the lateral column of erector spinae?","options":["Iliocostalis","Longissimus","Spinalis","Semispinalis","Multifidus"],"answer":0,"note":"From lateral to medial, erector spinae consists of iliocostalis, longissimus, and spinalis.","source":{"volume":5,"pages":[45]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u002","muscle":"Longissimus","region":"Trunk","priority":"important","focus":"name","prompt":"Which erector spinae group lies between iliocostalis and spinalis?","options":["Longissimus","Splenius","Multifidus","Rotatores","Semispinalis"],"answer":0,"note":"Longissimus is the intermediate column of erector spinae.","source":{"volume":5,"pages":[45]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u003","muscle":"Spinalis","region":"Trunk","priority":"important","focus":"name","prompt":"Which erector spinae group lies closest to the spinous processes?","options":["Spinalis","Longissimus","Iliocostalis","Splenius","Semispinalis"],"answer":0,"note":"Spinalis is the most medial erector spinae column.","source":{"volume":5,"pages":[45]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u004","muscle":"Semispinalis capitis","region":"Trunk","priority":"important","focus":"name","prompt":"Which muscle extends the head bilaterally and rotates it to the opposite side when acting unilaterally?","options":["Semispinalis capitis","Splenius capitis","Longissimus capitis","Rectus capitis posterior major","Obliquus capitis inferior"],"answer":0,"note":"Semispinalis capitis produces contralateral rotation; splenius capitis produces ipsilateral rotation.","source":{"volume":5,"pages":[46,47]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u005","muscle":"Multifidus","region":"Trunk","priority":"standard","focus":"name","prompt":"Which transversospinalis muscle typically spans two to four vertebral segments?","options":["Multifidus","Rotatores","Semispinalis","Spinalis","Iliocostalis"],"answer":0,"note":"The diagram contrasts multifidus at two to four segments with shorter rotatores and longer semispinalis.","source":{"volume":5,"pages":[46]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u006","muscle":"Rotatores","region":"Trunk","priority":"standard","focus":"name","prompt":"Which transversospinalis muscles typically span only one or two vertebral segments?","options":["Rotatores","Multifidus","Semispinalis","Longissimus","Splenius"],"answer":0,"note":"Rotatores are the short, deep transversospinalis muscles spanning one or two segments.","source":{"volume":5,"pages":[46]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u007","muscle":"Splenius capitis","region":"Trunk","priority":"important","focus":"action","prompt":"What is the main head movement produced by bilateral splenius capitis contraction?","options":["Head and neck extension","Head and neck flexion","Pure rightward head rotation","Pure leftward head rotation","Pure lateral neck flexion"],"answer":0,"note":"Bilateral splenius contraction extends the head.","source":{"volume":5,"pages":[44,46]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u008","muscle":"Diaphragm","region":"Trunk","priority":"essential","focus":"action","prompt":"What happens when the diaphragm contracts during inspiration?","options":["It flattens and increases thoracic volume","It domes upward and decreases thoracic volume","It flattens and decreases thoracic volume","It domes upward and increases thoracic volume","It relaxes upward without changing thoracic volume"],"answer":0,"note":"Contraction lowers and flattens the diaphragm, increasing thoracic volume.","source":{"volume":5,"pages":[52]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"}]},{"id":"u009","muscle":"External intercostals","region":"Trunk","priority":"important","focus":"action","prompt":"With the first rib stabilized, what is the principal respiratory action of the external intercostals?","options":["Elevate the ribs","Depress the ribs during forced expiration","Flex the trunk","Extend the trunk","Protract the scapula"],"answer":0,"note":"External intercostals elevate the ribs and assist inspiration.","source":{"volume":5,"pages":[49,53]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"},{"label":"Complete Anatomy · External intercostals","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-thorax/external-intercostal-muscles/24385"}]},{"id":"u010","muscle":"External oblique","region":"Trunk","priority":"essential","focus":"action","prompt":"Which movement pair can external oblique produce at the vertebral column?","options":["Trunk flexion and lateral bending","Trunk extension and lateral bending","Trunk extension and contralateral rotation","Head extension and ipsilateral rotation","Neck flexion and contralateral rotation"],"answer":0,"note":"External oblique can flex the trunk and contribute to lateral bending.","source":{"volume":5,"pages":[55,60]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u011","muscle":"Rectus abdominis","region":"Trunk","priority":"essential","focus":"action","prompt":"Which movement is a principal action of rectus abdominis?","options":["Flexion of the trunk","Extension of the trunk","Abduction of the hip","Elevation of the scapula","Extension of the neck"],"answer":0,"note":"Rectus abdominis flexes the trunk; do not treat axial rotation as its principal action.","source":{"volume":5,"pages":[55]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}],"correction":{"text":"The lecture also lists rotation; UAMS identifies trunk flexion as the principal action tested here.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}},{"id":"u012","muscle":"External urethral sphincter","region":"Trunk","priority":"important","focus":"action","prompt":"What is the principal action of the external urethral sphincter?","options":["Voluntarily constrict the urethra","Compress the urinary bladder to expel urine","Constrict the anal canal","Widen the urethral lumen","Compress the vestibular bulb"],"answer":0,"note":"The external urethral sphincter is skeletal muscle that contributes to voluntary urinary continence.","source":{"volume":5,"pages":[59]},"externalSources":[{"label":"UAMS · Pelvis and perineum","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-pelvis-and-perineum/"}]},{"id":"u013","muscle":"Rectus capitis posterior minor","region":"Trunk","priority":"standard","focus":"origin","prompt":"From which vertebra does rectus capitis posterior minor arise?","options":["Atlas (C1)","Axis (C2)","C3","C7","T1"],"answer":0,"note":"Rectus capitis posterior minor arises from C1 and attaches near the inferior nuchal line.","source":{"volume":5,"pages":[48]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u014","muscle":"Rectus capitis posterior major","region":"Trunk","priority":"standard","focus":"origin","prompt":"From which vertebra does rectus capitis posterior major arise?","options":["Axis (C2)","Atlas (C1)","C4","C7","T2"],"answer":0,"note":"Rectus capitis posterior major arises from the axis and inserts near the inferior nuchal line.","source":{"volume":5,"pages":[48]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u015","muscle":"Obliquus capitis superior","region":"Trunk","priority":"standard","focus":"origin","prompt":"Which landmark is the origin of obliquus capitis superior?","options":["Transverse process of the atlas","Spinous process of the axis","Posterior tubercle of the atlas","Spinous process of C7","Mastoid process"],"answer":0,"note":"Obliquus capitis superior runs from the atlas transverse process to the occipital bone.","source":{"volume":5,"pages":[48]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u016","muscle":"Obliquus capitis inferior","region":"Trunk","priority":"standard","focus":"origin","prompt":"Which landmark is the origin of obliquus capitis inferior?","options":["Spinous process of the axis","Transverse process of the atlas","Posterior tubercle of the atlas","Mastoid process","Superior nuchal line"],"answer":0,"note":"Obliquus capitis inferior runs from the axis spinous process to the atlas transverse process.","source":{"volume":5,"pages":[48]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u017","muscle":"Quadratus lumborum","region":"Trunk","priority":"important","focus":"origin","prompt":"Which bony landmark contributes to the origin of quadratus lumborum?","options":["Iliac crest","Pubic symphysis","Ischial spine","Xiphoid process","Ischial tuberosity"],"answer":0,"note":"Quadratus lumborum arises partly from the iliac crest and reaches the twelfth rib and lumbar transverse processes.","source":{"volume":5,"pages":[57]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u018","muscle":"Coccygeus","region":"Trunk","priority":"important","focus":"origin","prompt":"Which pelvic landmark is the origin of coccygeus?","options":["Ischial spine","Ischial tuberosity","Anterior superior iliac spine","Pubic symphysis","Iliac crest"],"answer":0,"note":"Coccygeus passes from the ischial spine to the sacrum and coccyx.","source":{"volume":5,"pages":[58]},"externalSources":[{"label":"UAMS · Pelvis and perineum","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-pelvis-and-perineum/"}]},{"id":"u019","muscle":"Splenius cervicis","region":"Trunk","priority":"important","focus":"insertion","prompt":"Where does splenius cervicis insert?","options":["Transverse processes of upper cervical vertebrae","Mastoid process","Mandibular angle","Spinous processes of lower lumbar vertebrae","Medial border of the scapula"],"answer":0,"note":"Splenius cervicis reaches upper cervical transverse processes; splenius capitis reaches the skull.","source":{"volume":5,"pages":[46]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u020","muscle":"Internal oblique","region":"Trunk","priority":"essential","focus":"insertion","prompt":"Which set contains insertion sites of internal oblique?","options":["Linea alba, pubic crest, and lower ribs","Iliac crest, inguinal ligament, and thoracolumbar fascia","Xiphoid process and costal cartilages 5–7","Lumbar transverse processes and twelfth rib","Sacrum and coccyx"],"answer":0,"note":"Internal oblique inserts through its aponeurosis into the linea alba and pubic region, and attaches to lower ribs.","source":{"volume":5,"pages":[55]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u021","muscle":"Transversus abdominis","region":"Trunk","priority":"essential","focus":"insertion","prompt":"Which pair includes major insertion sites of transversus abdominis?","options":["Linea alba and pubic crest","Xiphoid process and costal cartilages 5–7","Lumbar transverse processes and twelfth rib","Sacrum and coccyx","Ischial spines and pubic symphysis"],"answer":0,"note":"Transversus abdominis reaches the linea alba and pubic region through its aponeurosis.","source":{"volume":5,"pages":[55]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u022","muscle":"Levator ani","region":"Trunk","priority":"important","focus":"insertion","prompt":"Which site receives attachment from parts of levator ani?","options":["Coccyx","Twelfth rib","Xiphoid process","Lesser trochanter","Iliac crest"],"answer":0,"note":"Parts of levator ani attach to the coccyx and midline pelvic-floor structures; its subdivisions do not share every attachment.","source":{"volume":5,"pages":[58]},"externalSources":[{"label":"UAMS · Pelvis and perineum","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-pelvis-and-perineum/"}]},{"id":"u023","muscle":"Deep transverse perineal","region":"Trunk","priority":"standard","focus":"insertion","prompt":"Where does the deep transverse perineal muscle attach medially in the lecture description?","options":["Perineal body (central tendon of the perineum)","Central tendon of the diaphragm","Linea alba","Iliotibial tract","Thoracolumbar fascia"],"answer":0,"note":"The lecture describes a medial attachment to the perineal body, not the diaphragm central tendon.","source":{"volume":5,"pages":[59]},"externalSources":[{"label":"UAMS · Pelvis and perineum","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-pelvis-and-perineum/"}]},{"id":"u024","muscle":"Transversus thoracis","region":"Trunk","priority":"standard","focus":"insertion","prompt":"Which structures receive the lateral attachments of transversus thoracis?","options":["Costal cartilages of ribs 2–6","Angles of ribs 9–12","Transverse processes of C1–C4","Spinous processes of T7–T12","Medial border of the scapula"],"answer":0,"note":"Transversus thoracis spreads from the posterior sternum toward the internal surfaces of upper costal cartilages.","source":{"volume":5,"pages":[50]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"}]},{"id":"u025","muscle":"Latissimus dorsi","region":"Shoulder & arm","priority":"essential","focus":"name","prompt":"Which broad superficial back muscle arises partly from the thoracolumbar fascia and extends, adducts, and medially rotates the arm?","options":["Latissimus dorsi","Trapezius","Rhomboid major","Serratus anterior","Supraspinatus"],"answer":0,"note":"Latissimus dorsi has a broad trunk origin and acts on the humerus at the shoulder.","source":{"volume":5,"pages":[66]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"},{"label":"Complete Anatomy · Latissimus dorsi","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-back/latissimus-dorsi-muscle/20795"}]},{"id":"u026","muscle":"Levator scapulae","region":"Shoulder & arm","priority":"important","focus":"name","prompt":"Which muscle connects C1–C4 transverse processes to the superior medial border of the scapula?","options":["Levator scapulae","Rhomboid major","Pectoralis minor","Serratus anterior","Subclavius"],"answer":0,"note":"Levator scapulae descends from the upper cervical vertebrae to the superior medial scapula.","source":{"volume":5,"pages":[67]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u027","muscle":"Rhomboid minor","region":"Shoulder & arm","priority":"important","focus":"name","prompt":"Which small muscle lies superior to rhomboid major and attaches near the medial root of the scapular spine?","options":["Rhomboid minor","Teres minor","Subclavius","Pectoralis minor","Serratus posterior inferior"],"answer":0,"note":"Rhomboid minor is superior to rhomboid major at the medial scapular border.","source":{"volume":5,"pages":[67,68]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u028","muscle":"Coracobrachialis","region":"Shoulder & arm","priority":"important","focus":"name","prompt":"Which muscle runs from the coracoid process to the medial humeral shaft and does not cross the elbow?","options":["Coracobrachialis","Biceps brachii","Brachialis","Triceps brachii","Pectoralis minor"],"answer":0,"note":"Coracobrachialis crosses the shoulder but ends on the humeral shaft before reaching the elbow.","source":{"volume":6,"pages":[4]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u029","muscle":"Brachialis","region":"Shoulder & arm","priority":"essential","focus":"name","prompt":"Which elbow flexor lies deep to biceps brachii and inserts on the proximal ulna?","options":["Brachialis","Brachioradialis","Coracobrachialis","Supinator","Triceps brachii"],"answer":0,"note":"Brachialis lies beneath biceps and attaches to the ulnar coronoid process and tuberosity.","source":{"volume":6,"pages":[6]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u030","muscle":"Subscapularis","region":"Shoulder & arm","priority":"essential","focus":"name","prompt":"Which rotator cuff muscle occupies the anterior scapular fossa and inserts on the lesser tubercle?","options":["Subscapularis","Supraspinatus","Infraspinatus","Teres minor","Teres major"],"answer":0,"note":"Subscapularis is the anterior rotator cuff muscle and inserts on the lesser tubercle.","source":{"volume":5,"pages":[72,74]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u031","muscle":"Trapezius","region":"Shoulder & arm","priority":"essential","focus":"action","prompt":"With the vertebral attachments fixed, what is the main action of the middle trapezius fibers?","options":["Retract the scapula","Protract the scapula","Medially rotate the humerus","Laterally rotate the humerus","Flex the humerus"],"answer":0,"note":"The transverse middle fibers pull the scapula medially, producing retraction.","source":{"volume":5,"pages":[65]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"},{"label":"Complete Anatomy · Transverse trapezius","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-back/transverse-part-of-trapezius-muscle/19991"}]},{"id":"u032","muscle":"Serratus anterior","region":"Shoulder & arm","priority":"essential","focus":"action","prompt":"Which action is characteristic of serratus anterior during pushing?","options":["Hold the scapula against the thoracic wall","Retract the scapula toward the vertebral column","Elevate the clavicle without scapular protraction","Extend the elbow","Medially rotate the humerus"],"answer":0,"note":"Serratus anterior stabilizes the scapula against the chest wall during pushing.","source":{"volume":5,"pages":[70]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u033","muscle":"Deltoid","region":"Shoulder & arm","priority":"essential","focus":"action","prompt":"What is the principal shoulder action of the middle deltoid fibers?","options":["Abduction","Adduction","Flexion","Extension","Medial rotation"],"answer":0,"note":"The middle deltoid is a powerful abductor of the arm at the shoulder.","source":{"volume":5,"pages":[72]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u034","muscle":"Teres major","region":"Shoulder & arm","priority":"essential","focus":"action","prompt":"Which movement pair describes teres major at the shoulder?","options":["Adduction and medial rotation","Abduction and lateral rotation","Abduction and medial rotation","Adduction and lateral rotation","Flexion and lateral rotation"],"answer":0,"note":"Teres major adducts and medially rotates the arm; it is not a rotator cuff member.","source":{"volume":5,"pages":[74]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u035","muscle":"Biceps brachii","region":"Shoulder & arm","priority":"essential","focus":"action","prompt":"Which action pair is characteristic of biceps brachii?","options":["Elbow flexion and forearm supination","Elbow extension and forearm pronation","Wrist flexion and ulnar deviation","Finger extension and wrist extension","Shoulder adduction and elbow extension"],"answer":0,"note":"Biceps brachii flexes the elbow and assists supination because its distal tendon reaches the radius.","source":{"volume":6,"pages":[6]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u036","muscle":"Triceps brachii","region":"Shoulder & arm","priority":"essential","focus":"action","prompt":"What is the principal action shared by all three heads of triceps brachii?","options":["Elbow extension","Elbow flexion","Forearm pronation","Wrist extension","Shoulder abduction"],"answer":0,"note":"All three heads converge on the olecranon to extend the elbow.","source":{"volume":6,"pages":[5]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u037","muscle":"Rhomboid major","region":"Shoulder & arm","priority":"important","focus":"origin","prompt":"Using the corrected standard attachment, which spinous processes give origin to rhomboid major?","options":["T2–T5","C1–C4","C7–T1","T7–T12","L1–L5"],"answer":0,"note":"Rhomboid major typically arises from T2–T5 spinous processes.","source":{"volume":5,"pages":[67]},"correction":{"text":"The lecture gives T1–T6; Complete Anatomy specifies the standard T2–T5 origin.","url":"https://www.elsevier.com/resources/anatomy/muscular-system/muscles-of-back/rhomboid-major-muscle/20614"},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u038","muscle":"Pectoralis minor","region":"Shoulder & arm","priority":"important","focus":"origin","prompt":"Which ribs give origin to pectoralis minor?","options":["Ribs 3–5","Ribs 1–2","Ribs 6–8","Ribs 9–12","Ribs 10–12"],"answer":0,"note":"Pectoralis minor originates on ribs 3–5 and reaches the coracoid process.","source":{"volume":5,"pages":[70]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u039","muscle":"Subclavius","region":"Shoulder & arm","priority":"standard","focus":"origin","prompt":"Which structure contributes to the origin of subclavius?","options":["First rib and its costal cartilage","Third rib and its costal cartilage","Coracoid process","Scapular spine","Lateral humeral epicondyle"],"answer":0,"note":"Subclavius extends from the first rib–costal cartilage region to the inferior clavicle.","source":{"volume":5,"pages":[70]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u040","muscle":"Supraspinatus","region":"Shoulder & arm","priority":"essential","focus":"origin","prompt":"Where does supraspinatus originate?","options":["Supraspinous fossa","Infraspinous fossa","Subscapular fossa","Inferior scapular angle","Coracoid process"],"answer":0,"note":"Supraspinatus originates above the scapular spine in the supraspinous fossa.","source":{"volume":5,"pages":[73]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u041","muscle":"Infraspinatus","region":"Shoulder & arm","priority":"essential","focus":"origin","prompt":"Where does infraspinatus originate?","options":["Infraspinous fossa","Supraspinous fossa","Subscapular fossa","Coracoid process","Acromion"],"answer":0,"note":"Infraspinatus occupies the posterior scapular fossa below the spine.","source":{"volume":5,"pages":[73]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u042","muscle":"Biceps brachii","region":"Shoulder & arm","priority":"essential","focus":"origin","prompt":"Which scapular landmark is the origin of the long head of biceps brachii?","options":["Supraglenoid tubercle","Infraglenoid tubercle","Coracoid process","Inferior angle","Spine of the scapula"],"answer":0,"note":"The long head arises from the supraglenoid region; the short head arises from the coracoid process.","source":{"volume":6,"pages":[6]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u043","muscle":"Pectoralis major","region":"Shoulder & arm","priority":"essential","focus":"insertion","prompt":"Where does pectoralis major insert on the proximal humerus?","options":["Lateral lip of the intertubercular sulcus","Floor of the intertubercular sulcus","Medial lip of the intertubercular sulcus","Lesser tubercle","Deltoid tuberosity"],"answer":0,"note":"Pectoralis major inserts on the lateral lip of the intertubercular sulcus.","source":{"volume":5,"pages":[69]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u044","muscle":"Teres minor","region":"Shoulder & arm","priority":"essential","focus":"insertion","prompt":"Which proximal humeral structure receives the insertion of teres minor?","options":["Greater tubercle","Lesser tubercle","Medial lip of the intertubercular sulcus","Deltoid tuberosity","Lateral epicondyle"],"answer":0,"note":"Teres minor inserts on the greater tubercle, unlike teres major on the intertubercular sulcus medial lip.","source":{"volume":5,"pages":[73,74]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u045","muscle":"Latissimus dorsi","region":"Shoulder & arm","priority":"essential","focus":"insertion","prompt":"Using the corrected standard attachment, where does latissimus dorsi insert?","options":["Floor of the intertubercular sulcus","Lateral lip of the intertubercular sulcus","Medial lip of the intertubercular sulcus","Greater tubercle","Deltoid tuberosity"],"answer":0,"note":"Latissimus dorsi inserts on the groove floor between pectoralis major and teres major.","source":{"volume":5,"pages":[66,74]},"correction":{"text":"The lecture incorrectly labels the latissimus insertion as medial lip; the standard attachment is the groove floor.","url":"https://anatomy.ttuhscep.edu/musculoskeletal_system/introback_tables.html"},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u046","muscle":"Deltoid","region":"Shoulder & arm","priority":"essential","focus":"insertion","prompt":"Which humeral landmark receives the deltoid insertion?","options":["Deltoid tuberosity","Greater tubercle","Lesser tubercle","Medial epicondyle","Anatomical neck"],"answer":0,"note":"The deltoid converges from the shoulder girdle onto the deltoid tuberosity.","source":{"volume":5,"pages":[72]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u047","muscle":"Triceps brachii","region":"Shoulder & arm","priority":"essential","focus":"insertion","prompt":"Where does the common distal tendon of triceps brachii insert?","options":["Olecranon of the ulna","Coronoid process of the ulna","Radial tuberosity","Radial styloid process","Medial humeral epicondyle"],"answer":0,"note":"The triceps tendon reaches the olecranon, allowing extension at the elbow.","source":{"volume":6,"pages":[5]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u048","muscle":"Serratus anterior","region":"Shoulder & arm","priority":"essential","focus":"insertion","prompt":"Where does serratus anterior insert?","options":["Anterior surface of the medial scapular border","Posterior surface of the lateral scapular border","Coracoid tip","Scapular spine","Greater humeral tubercle"],"answer":0,"note":"Serratus anterior inserts along the anterior aspect of the medial border of the scapula.","source":{"volume":5,"pages":[70]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u049","muscle":"Pronator teres","region":"Forearm & hand","priority":"essential","focus":"name","prompt":"Which muscle runs from the medial epicondyle and ulnar coronoid process to the lateral mid-radius?","options":["Pronator teres","Pronator quadratus","Supinator","Flexor carpi radialis","Brachioradialis"],"answer":0,"note":"Pronator teres crosses obliquely toward the lateral radius and produces pronation.","source":{"volume":6,"pages":[10]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u050","muscle":"Palmaris longus","region":"Forearm & hand","priority":"important","focus":"name","prompt":"Which superficial forearm muscle has a long tendon that blends with the palmar aponeurosis?","options":["Palmaris longus","Flexor carpi radialis","Flexor carpi ulnaris","Flexor pollicis longus","Pronator teres"],"answer":0,"note":"Palmaris longus reaches the palmar aponeurosis and may be absent without major functional loss.","source":{"volume":6,"pages":[10]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u051","muscle":"Flexor digitorum superficialis","region":"Forearm & hand","priority":"essential","focus":"name","prompt":"Which finger flexor inserts directly on the middle phalanges of digits 2–5?","options":["Flexor digitorum superficialis","Flexor digitorum profundus","Lumbricals","Flexor pollicis longus","Palmar interossei"],"answer":0,"note":"Flexor digitorum superficialis reaches the middle phalanges; profundus continues to the distal phalanges.","source":{"volume":6,"pages":[11,23]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u052","muscle":"Flexor digitorum profundus","region":"Forearm & hand","priority":"essential","focus":"name","prompt":"Which finger flexor arises mainly from the ulna and interosseous membrane and reaches the distal phalanges of digits 2–5?","options":["Flexor digitorum profundus","Flexor digitorum superficialis","Flexor pollicis longus","Lumbricals","Palmar interossei"],"answer":0,"note":"Flexor digitorum profundus extends farther distally than superficialis.","source":{"volume":6,"pages":[14]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u053","muscle":"Pronator quadratus","region":"Forearm & hand","priority":"essential","focus":"name","prompt":"Which deep distal forearm muscle runs transversely from the distal ulna to the distal radius?","options":["Pronator quadratus","Pronator teres","Supinator","Anconeus","Flexor pollicis longus"],"answer":0,"note":"Pronator quadratus is the square muscle crossing between the distal forearm bones.","source":{"volume":6,"pages":[14]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u054","muscle":"Brachioradialis","region":"Forearm & hand","priority":"essential","focus":"name","prompt":"Which muscle arises from the lateral supracondylar region, ends near the radial styloid, and flexes the elbow?","options":["Brachioradialis","Extensor carpi radialis longus","Brachialis","Supinator","Anconeus"],"answer":0,"note":"Brachioradialis is grouped with the posterior compartment but acts as an elbow flexor.","source":{"volume":6,"pages":[18]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u055","muscle":"Extensor pollicis longus","region":"Forearm & hand","priority":"essential","focus":"name","prompt":"Which deep posterior forearm muscle inserts on the distal phalanx of the thumb and extends it?","options":["Extensor pollicis longus","Extensor pollicis brevis","Abductor pollicis longus","Abductor pollicis brevis","Flexor pollicis longus"],"answer":0,"note":"Extensor pollicis longus reaches the distal thumb phalanx; brevis stops at the proximal phalanx.","source":{"volume":6,"pages":[19]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u056","muscle":"Abductor pollicis brevis","region":"Forearm & hand","priority":"important","focus":"name","prompt":"Which short thumb abductor is an intrinsic thenar muscle rather than a muscle of the forearm?","options":["Abductor pollicis brevis","Abductor pollicis longus","Extensor pollicis brevis","Extensor pollicis longus","Flexor pollicis longus"],"answer":0,"note":"Abductor pollicis brevis lies in the thenar region; the other listed muscles have forearm muscle bellies.","source":{"volume":6,"pages":[19,25]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u057","muscle":"Flexor carpi radialis","region":"Forearm & hand","priority":"important","focus":"action","prompt":"Which action pair is produced by flexor carpi radialis?","options":["Wrist flexion and radial deviation","Wrist extension and radial deviation","Wrist flexion and ulnar deviation","Wrist extension and ulnar deviation","Elbow flexion and forearm supination"],"answer":0,"note":"Flexor carpi radialis flexes the wrist and contributes to radial deviation, also called wrist abduction.","source":{"volume":6,"pages":[10]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u058","muscle":"Flexor carpi ulnaris","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which action pair is produced by flexor carpi ulnaris?","options":["Wrist flexion and ulnar deviation","Wrist flexion and radial deviation","Wrist extension and ulnar deviation","Wrist extension and radial deviation","Elbow flexion and forearm supination"],"answer":0,"note":"FCU combines wrist flexion with ulnar deviation; FCR combines flexion with radial deviation.","source":{"volume":6,"pages":[11]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u059","muscle":"Extensor digiti minimi","region":"Forearm & hand","priority":"important","focus":"action","prompt":"Which digit is specifically extended by extensor digiti minimi?","options":["Little finger","Index finger","Middle finger","Ring finger","Thumb"],"answer":0,"note":"Extensor digiti minimi supplies an additional extensor tendon to the little finger.","source":{"volume":6,"pages":[17]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u060","muscle":"Extensor digitorum","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which joint movement is a major action of extensor digitorum?","options":["Extension of MCP joints of digits 2–5","Flexion of DIP joints of digits 2–5","Flexion of the thumb IP joint","Opposition at the thumb CMC joint","Pronation at the radioulnar joints"],"answer":0,"note":"Extensor digitorum primarily extends the metacarpophalangeal joints and acts through the extensor expansions.","source":{"volume":6,"pages":[17,23]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u061","muscle":"Supinator","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which movement is produced by supinator?","options":["Forearm supination","Forearm pronation","Elbow flexion","Elbow extension","Wrist radial deviation"],"answer":0,"note":"Supinator produces forearm supination; biceps is also a powerful supinator when the elbow is flexed.","source":{"volume":6,"pages":[19]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}],"correction":{"text":"The lecture calls supinator the strongest; UAMS also identifies biceps as a powerful supinator with the elbow flexed.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}},{"id":"u062","muscle":"Opponens pollicis","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which movement best matches opponens pollicis?","options":["Thumb opposition","Thumb interphalangeal extension","Thumb interphalangeal flexion","Pure thumb adduction","Pure thumb abduction"],"answer":0,"note":"Opponens pollicis moves the first metacarpal to help bring the thumb across the palm.","source":{"volume":6,"pages":[24,25]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u063","muscle":"Palmar interossei","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Relative to the middle finger as the hand axis, what is the characteristic action of the palmar interossei?","options":["Adduct the fingers","Abduct the fingers","Oppose the thumb","Extend the wrist","Supinate the forearm"],"answer":0,"note":"PAD: palmar interossei adduct the fingers toward the middle-finger axis.","source":{"volume":6,"pages":[27]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u064","muscle":"Dorsal interossei","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Relative to the middle finger as the hand axis, what is the characteristic action of the dorsal interossei?","options":["Abduct the fingers","Adduct the fingers","Flex the thumb IP joint","Extend the wrist","Pronate the forearm"],"answer":0,"note":"DAB: dorsal interossei abduct the fingers away from the middle-finger axis.","source":{"volume":6,"pages":[27]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u065","muscle":"Extensor indicis","region":"Forearm & hand","priority":"important","focus":"origin","prompt":"Using the corrected standard attachment, where does extensor indicis arise?","options":["Distal posterior ulna and adjacent interosseous membrane","Distal anterior radius and adjacent interosseous membrane","Medial humeral epicondyle","Lateral supracondylar ridge of the humerus","Palmar surfaces of metacarpals 2, 4, and 5"],"answer":0,"note":"Extensor indicis arises from the distal ulna and interosseous membrane, not from the radius.","source":{"volume":6,"pages":[20]},"correction":{"text":"The lecture adds the radius; anatomical research describes distal ulna and interosseous membrane as the usual origin.","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7808791/"},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u066","muscle":"Flexor pollicis longus","region":"Forearm & hand","priority":"essential","focus":"origin","prompt":"Which pair gives origin to flexor pollicis longus?","options":["Anterior radius and interosseous membrane","Posterior ulna and interosseous membrane","Lateral epicondyle and radial head","Pisiform and fifth metacarpal","Palmar aponeurosis and skin"],"answer":0,"note":"Flexor pollicis longus occupies the deep anterior forearm and arises from the radius and interosseous membrane.","source":{"volume":6,"pages":[14]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u067","muscle":"Pronator quadratus","region":"Forearm & hand","priority":"essential","focus":"origin","prompt":"Where does pronator quadratus originate?","options":["Distal quarter of the ulna","Proximal third of the radius","Medial humeral epicondyle","Lateral humeral epicondyle","Second metacarpal base"],"answer":0,"note":"Pronator quadratus crosses from the distal ulna to the distal radius.","source":{"volume":6,"pages":[14]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u068","muscle":"Anconeus","region":"Forearm & hand","priority":"standard","focus":"origin","prompt":"Which landmark is the origin of anconeus?","options":["Lateral humeral epicondyle","Medial humeral epicondyle","Radial tuberosity","Coronoid process","Distal radial styloid"],"answer":0,"note":"Anconeus is a small posterior elbow muscle originating from the lateral epicondyle.","source":{"volume":6,"pages":[18]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u069","muscle":"Abductor pollicis longus","region":"Forearm & hand","priority":"important","focus":"origin","prompt":"Which region gives origin to abductor pollicis longus?","options":["Posterior radius, posterior ulna, and interosseous membrane","Anterior radius and radial tuberosity","Medial epicondyle and coronoid process","Pisiform and hook of hamate","Palmar aponeurosis and flexor retinaculum"],"answer":0,"note":"Abductor pollicis longus arises deeply in the posterior forearm from both bones and the interosseous membrane.","source":{"volume":6,"pages":[19]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u070","muscle":"Lumbricals","region":"Forearm & hand","priority":"essential","focus":"origin","prompt":"From which structures do the hand lumbricals arise?","options":["Flexor digitorum profundus tendons","Flexor digitorum superficialis tendons","Extensor digitorum tendons","Palmar aponeurosis","Dorsal surfaces of the metacarpals"],"answer":0,"note":"The lumbricals unusually arise from FDP tendons rather than directly from bones.","source":{"volume":6,"pages":[27]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u071","muscle":"Dorsal interossei","region":"Forearm & hand","priority":"essential","focus":"origin","prompt":"Which attachment pattern describes the origins of the dorsal interossei?","options":["Adjacent sides of neighboring metacarpals","Only the palmar surfaces of metacarpals 2, 4, and 5","Flexor digitorum profundus tendons","Distal ulna and interosseous membrane","Flexor retinaculum alone"],"answer":0,"note":"Dorsal interossei arise between adjacent metacarpals, producing their bipennate arrangement.","source":{"volume":6,"pages":[27]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u072","muscle":"Palmar interossei","region":"Forearm & hand","priority":"essential","focus":"origin","prompt":"Which metacarpals give origin to the three palmar interossei in the lecture description?","options":["Metacarpals 2, 4, and 5","Metacarpals 1, 2, and 3","Metacarpals 1, 3, and 5","Metacarpals 2, 3, and 4","Metacarpals 1, 2, and 5"],"answer":0,"note":"The usual three palmar interossei arise from metacarpals 2, 4, and 5, facing the middle-finger axis.","source":{"volume":6,"pages":[27]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u073","muscle":"Extensor carpi radialis longus","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"On which metacarpal does extensor carpi radialis longus insert?","options":["Second metacarpal","First metacarpal","Third metacarpal","Fourth metacarpal","Fifth metacarpal"],"answer":0,"note":"ECRL inserts at the second metacarpal base; ECRB inserts at the third.","source":{"volume":6,"pages":[18]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u074","muscle":"Extensor carpi radialis brevis","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"On which metacarpal does extensor carpi radialis brevis insert?","options":["Third metacarpal","First metacarpal","Second metacarpal","Fourth metacarpal","Fifth metacarpal"],"answer":0,"note":"ECRB inserts at the third metacarpal base.","source":{"volume":6,"pages":[18]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u075","muscle":"Extensor carpi ulnaris","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"On which metacarpal does extensor carpi ulnaris insert?","options":["Fifth metacarpal","First metacarpal","Second metacarpal","Third metacarpal","Fourth metacarpal"],"answer":0,"note":"ECU inserts at the base of the fifth metacarpal.","source":{"volume":6,"pages":[18]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u076","muscle":"Extensor pollicis brevis","region":"Forearm & hand","priority":"essential","focus":"insertion","prompt":"Where does extensor pollicis brevis insert?","options":["Proximal phalanx of the thumb","Distal phalanx of the thumb","First metacarpal base","Second metacarpal base","Proximal phalanx of the index finger"],"answer":0,"note":"Extensor pollicis brevis reaches the proximal thumb phalanx; longus reaches the distal phalanx.","source":{"volume":6,"pages":[19]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u077","muscle":"Flexor pollicis longus","region":"Forearm & hand","priority":"essential","focus":"insertion","prompt":"Where does flexor pollicis longus insert?","options":["Distal phalanx of the thumb","Proximal phalanx of the thumb","First metacarpal base","Second metacarpal base","Distal phalanx of the index finger"],"answer":0,"note":"FPL reaches the distal thumb phalanx, enabling flexion of the thumb interphalangeal joint.","source":{"volume":6,"pages":[14]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u078","muscle":"Flexor carpi radialis","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"Which metacarpal bases receive the insertion of flexor carpi radialis in the lecture?","options":["Second and third","First and second","Third and fourth","Fourth and fifth","First and fifth"],"answer":0,"note":"FCR principally reaches the second metacarpal base, with an attachment to the third.","source":{"volume":6,"pages":[10]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u079","muscle":"Abductor digiti minimi","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"Which structure receives the digital insertion of abductor digiti minimi in the hand?","options":["Proximal phalanx of the little finger","Distal phalanx of the little finger","Middle phalanx of the ring finger","Proximal phalanx of the thumb","First metacarpal shaft"],"answer":0,"note":"Abductor digiti minimi reaches the proximal phalanx of the little finger.","source":{"volume":6,"pages":[26]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u080","muscle":"Flexor pollicis brevis","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"Which structure receives the insertion of flexor pollicis brevis?","options":["Proximal phalanx of the thumb","Distal phalanx of the thumb","First metacarpal shaft","Second metacarpal base","Proximal phalanx of the index finger"],"answer":0,"note":"Flexor pollicis brevis reaches the proximal thumb phalanx; flexor pollicis longus reaches the distal phalanx.","source":{"volume":6,"pages":[25]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u081","muscle":"Internal intercostals","region":"Trunk","priority":"important","focus":"name","prompt":"Which intercostal layer lies immediately deep to external intercostals and has fibers running in the opposite direction?","options":["Internal intercostals","Innermost intercostals","Subcostales","Transversus thoracis","Levatores costarum"],"answer":0,"note":"Internal intercostals lie between the external and innermost intercostal layers.","source":{"volume":5,"pages":[49]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"}]},{"id":"u082","muscle":"Innermost intercostals","region":"Trunk","priority":"important","focus":"name","prompt":"Which intercostal muscles share the internal intercostal fiber direction but lie deepest?","options":["Innermost intercostals","External intercostals","Internal intercostals","Levatores costarum","Serratus posterior inferior"],"answer":0,"note":"Innermost intercostals have the same fiber direction as internal intercostals and lie deeper than the intercostal neurovascular bundle.","source":{"volume":5,"pages":[49]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"}]},{"id":"u083","muscle":"Subcostales","region":"Trunk","priority":"standard","focus":"name","prompt":"Which muscles on the internal lower thoracic wall connect nonadjacent ribs, spanning more than one intercostal space?","options":["Subcostales","External intercostals","Internal intercostals","Transversus thoracis","Levatores costarum"],"answer":0,"note":"Subcostales connect separated ribs; transversus thoracis connects sternum to costal cartilages, and levatores costarum begin on vertebral transverse processes.","source":{"volume":5,"pages":[50]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"}]},{"id":"u084","muscle":"Levatores costarum","region":"Trunk","priority":"standard","focus":"origin","prompt":"Which vertebral landmarks give origin to levatores costarum?","options":["Transverse processes of C7–T11","Spinous processes of C7–T11","Transverse processes of C1–C4","Spinous processes of T11–L2","Bodies of L1–L3"],"answer":0,"note":"Levatores costarum arise from transverse processes and descend to ribs.","source":{"volume":5,"pages":[51]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"}]},{"id":"u085","muscle":"Serratus posterior superior","region":"Trunk","priority":"standard","focus":"origin","prompt":"Which attachment set gives origin to serratus posterior superior?","options":["Nuchal ligament and C7–T3 spinous processes","Thoracolumbar fascia and T11–L2 spinous processes","C1–C4 transverse processes","T2–T5 vertebral bodies","L1–L3 vertebral bodies"],"answer":0,"note":"Serratus posterior superior arises in the lower cervical and upper thoracic midline.","source":{"volume":5,"pages":[51]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u086","muscle":"Serratus posterior inferior","region":"Trunk","priority":"standard","focus":"insertion","prompt":"Which ribs receive serratus posterior inferior?","options":["Ribs 9–12","Ribs 1–4","Ribs 2–5","Ribs 3–6","Ribs 5–8"],"answer":0,"note":"Serratus posterior inferior reaches the lowest four ribs.","source":{"volume":5,"pages":[51]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u087","muscle":"Puborectalis","region":"Trunk","priority":"important","focus":"name","prompt":"Which muscle completes the levator ani group alongside pubococcygeus and iliococcygeus?","options":["Puborectalis","Coccygeus","Obturator internus","Deep transverse perineal","External urethral sphincter"],"answer":0,"note":"Levator ani comprises puborectalis, pubococcygeus, and iliococcygeus. Coccygeus is a separate pelvic diaphragm muscle.","source":{"volume":5,"pages":[58]},"externalSources":[{"label":"UAMS · Pelvis and perineum","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-pelvis-and-perineum/"}]},{"id":"u088","muscle":"External oblique","region":"Trunk","priority":"essential","focus":"origin","prompt":"Which ribs provide the broad muscular origin of external oblique?","options":["Ribs 5–12","Ribs 1–4","Ribs 2–6","Ribs 3–5","Ribs 10–12 only"],"answer":0,"note":"External oblique arises from the lower eight ribs.","source":{"volume":5,"pages":[55]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u089","muscle":"Transversus abdominis","region":"Trunk","priority":"essential","focus":"action","prompt":"Which action most directly matches transversus abdominis?","options":["Compress the abdominal contents","Extend the lumbar spine","Elevate the ribs","Retract the scapula","Extend the hip"],"answer":0,"note":"Transversus abdominis is the deepest flat abdominal muscle and compresses the abdominal contents.","source":{"volume":5,"pages":[55]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u090","muscle":"Diaphragm","region":"Trunk","priority":"essential","focus":"insertion","prompt":"Where do the muscular fibers of the diaphragm converge?","options":["Central tendon of the diaphragm","Linea alba","Thoracolumbar fascia","Perineal body","Rectus sheath"],"answer":0,"note":"The diaphragm has peripheral skeletal attachments and a central tendinous insertion.","source":{"volume":5,"pages":[52]},"externalSources":[{"label":"UAMS · Thorax","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-thorax/"}]},{"id":"u091","muscle":"Rectus abdominis","region":"Trunk","priority":"essential","focus":"origin","prompt":"Which pair gives origin to rectus abdominis?","options":["Pubic crest and pubic symphysis","Iliac crest and inguinal ligament","Xiphoid process and costal margin","Lumbar transverse processes and twelfth rib","Ischial spine and sacrotuberous ligament"],"answer":0,"note":"Rectus abdominis ascends from the pubis toward the xiphoid process and costal cartilages 5–7.","source":{"volume":5,"pages":[55]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u092","muscle":"Quadratus lumborum","region":"Trunk","priority":"important","focus":"action","prompt":"Which action pair describes quadratus lumborum?","options":["Lateral bending of the trunk and fixation of rib 12","Trunk flexion and depression of ribs 2–5","Scapular retraction and upward rotation","Hip extension and knee flexion","Pelvic-floor elevation and urethral constriction"],"answer":0,"note":"Quadratus lumborum bends the trunk laterally and stabilizes the twelfth rib.","source":{"volume":5,"pages":[57,60]},"externalSources":[{"label":"UAMS · Abdomen","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-abdominal-region/"}]},{"id":"u093","muscle":"Teres major","region":"Shoulder & arm","priority":"essential","focus":"insertion","prompt":"Where does teres major insert on the humerus?","options":["Medial lip of the intertubercular sulcus","Floor of the intertubercular sulcus","Lateral lip of the intertubercular sulcus","Greater tubercle","Deltoid tuberosity"],"answer":0,"note":"The medial lip is also called the crest of the lesser tubercle.","source":{"volume":5,"pages":[74]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u094","muscle":"Triceps brachii","region":"Shoulder & arm","priority":"essential","focus":"origin","prompt":"Which scapular landmark gives origin to the long head of triceps brachii?","options":["Infraglenoid tubercle","Supraglenoid tubercle","Coracoid process","Acromion","Superior angle"],"answer":0,"note":"The triceps long head originates below the glenoid; the biceps long head originates above it.","source":{"volume":6,"pages":[5]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u095","muscle":"Pectoralis minor","region":"Shoulder & arm","priority":"important","focus":"insertion","prompt":"Which scapular landmark receives pectoralis minor?","options":["Coracoid process","Acromion","Spine of the scapula","Inferior angle","Infraglenoid tubercle"],"answer":0,"note":"Pectoralis minor reaches the coracoid process; pectoralis major reaches the humerus.","source":{"volume":5,"pages":[70]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u096","muscle":"Rhomboid major","region":"Shoulder & arm","priority":"important","focus":"action","prompt":"What does rhomboid major do to the scapula?","options":["Retract it toward the vertebral column","Protract it around the thoracic wall","Rotate it upward during overhead reach","Depress it without retraction","Move the humeral head without moving the scapula"],"answer":0,"note":"Rhomboid major retracts and elevates the scapula and contributes to downward rotation.","source":{"volume":5,"pages":[67]},"externalSources":[{"label":"UAMS · Back","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-back-region/"}]},{"id":"u097","muscle":"Pectoralis major","region":"Shoulder & arm","priority":"essential","focus":"origin","prompt":"Which part of the clavicle gives origin to the clavicular head of pectoralis major?","options":["Anterior surface of the medial half","Posterior surface of the lateral third","Inferior surface of the middle third","Superior surface of the lateral third","Acromial end only"],"answer":0,"note":"The clavicular head arises medially; the deltoid arises from the lateral third of the clavicle.","source":{"volume":5,"pages":[69]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u098","muscle":"Coracobrachialis","region":"Shoulder & arm","priority":"important","focus":"action","prompt":"Which action pair is produced by coracobrachialis at the shoulder?","options":["Flexion and adduction","Extension and adduction","Abduction and lateral rotation","Extension and lateral rotation","Elbow flexion and forearm supination"],"answer":0,"note":"Coracobrachialis flexes and adducts the arm but does not cross the elbow.","source":{"volume":6,"pages":[4]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u099","muscle":"Adductor pollicis","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which movement is characteristic of adductor pollicis?","options":["Thumb adduction","Thumb interphalangeal extension","Index finger abduction","Little-finger opposition","Wrist radial deviation"],"answer":0,"note":"Adductor pollicis adducts the thumb; it is distinct from the thumb abductors.","source":{"volume":6,"pages":[25]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u100","muscle":"Opponens digiti minimi","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"Where does opponens digiti minimi insert?","options":["Shaft of the fifth metacarpal","Base of the fifth proximal phalanx","Base of the fifth distal phalanx","Shaft of the first metacarpal","Hook of the hamate"],"answer":0,"note":"Opponens digiti minimi rotates the fifth metacarpal rather than attaching to a little-finger phalanx.","source":{"volume":6,"pages":[26]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u101","muscle":"Flexor digiti minimi brevis","region":"Forearm & hand","priority":"important","focus":"action","prompt":"Which movement is performed by flexor digiti minimi brevis in the hand?","options":["Flexion of the little-finger MCP joint","Extension of the little-finger MCP joint","Flexion of the thumb IP joint","Adduction of the index finger","Extension of the wrist"],"answer":0,"note":"Flexor digiti minimi brevis is a hypothenar muscle that flexes the little finger at its MCP joint.","source":{"volume":6,"pages":[24,26]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u102","muscle":"Palmaris brevis","region":"Forearm & hand","priority":"standard","focus":"name","prompt":"Which thin muscle lies superficially over the hypothenar region and moves the skin along the ulnar side of the palm?","options":["Palmaris brevis","Palmaris longus","Opponens digiti minimi","Flexor digiti minimi brevis","Adductor pollicis"],"answer":0,"note":"Palmaris brevis acts on palmar skin; palmaris longus has a forearm belly and reaches the palmar aponeurosis.","source":{"volume":6,"pages":[26]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u103","muscle":"Abductor pollicis longus","region":"Forearm & hand","priority":"important","focus":"insertion","prompt":"Where does abductor pollicis longus insert?","options":["Base of the first metacarpal","Base of the first proximal phalanx","Base of the first distal phalanx","Base of the second metacarpal","Radial styloid process"],"answer":0,"note":"APL reaches the first metacarpal, whereas the short thenar abductor reaches the proximal thumb phalanx.","source":{"volume":6,"pages":[19]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u104","muscle":"Lumbricals","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which finger movement pair is characteristic of the hand lumbricals?","options":["MCP flexion with IP extension","MCP extension with IP flexion","MCP flexion with IP flexion","MCP extension with IP extension","Finger abduction without any joint flexion"],"answer":0,"note":"Lumbricals pass to the extensor expansions, allowing MCP flexion with PIP and DIP extension.","source":{"volume":6,"pages":[27,28]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u105","muscle":"Flexor digitorum superficialis","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which movement is directly produced by flexor digitorum superficialis?","options":["Flexion of PIP joints of digits 2–5","Flexion of DIP joints of digits 2–5","Extension of PIP joints of digits 2–5","Extension of MCP joints of digits 2–5","Flexion of the thumb IP joint"],"answer":0,"note":"FDS ends on the middle phalanges and directly flexes the PIP joints; FDP continues to the distal phalanges.","source":{"volume":6,"pages":[11,23]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u106","muscle":"Flexor digitorum profundus","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which action most specifically distinguishes flexor digitorum profundus from flexor digitorum superficialis?","options":["Flexing the DIP joints of digits 2–5","Flexing the PIP joints of digits 2–5","Flexing the MCP joints of digits 2–5","Extending the DIP joints of digits 2–5","Abducting digits 2–5"],"answer":0,"note":"FDP reaches the distal phalanges and can flex the DIP joints; FDS cannot directly flex them.","source":{"volume":6,"pages":[14,23]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u107","muscle":"Pronator teres","region":"Forearm & hand","priority":"essential","focus":"action","prompt":"Which movement is the primary action of pronator teres?","options":["Forearm pronation","Forearm supination","Elbow extension","Wrist extension","Finger adduction"],"answer":0,"note":"Pronator teres pulls the radius across the ulna during pronation.","source":{"volume":6,"pages":[10]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u108","muscle":"Anconeus","region":"Forearm & hand","priority":"standard","focus":"insertion","prompt":"Which structures receive anconeus?","options":["Lateral olecranon and adjacent proximal ulna","Radial tuberosity and bicipital aponeurosis","Distal radial styloid and adjacent radius","Coronoid process and ulnar tuberosity","Second and third metacarpal bases"],"answer":0,"note":"Anconeus runs from the lateral epicondyle to the lateral olecranon and proximal posterior ulna.","source":{"volume":6,"pages":[18]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u109","muscle":"Supinator","region":"Forearm & hand","priority":"essential","focus":"insertion","prompt":"Which part of the radius receives supinator?","options":["Proximal third of the radius","Lateral midshaft of the radius","Distal quarter of the radius","Tip of the radial styloid process","Distal articular surface of the radius"],"answer":0,"note":"Supinator wraps around and attaches to the proximal radius.","source":{"volume":6,"pages":[19]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"u110","muscle":"Opponens pollicis","region":"Forearm & hand","priority":"essential","focus":"insertion","prompt":"Where does opponens pollicis insert?","options":["Shaft of the first metacarpal","Base of the first proximal phalanx","Base of the first distal phalanx","Base of the second metacarpal","Scaphoid tubercle"],"answer":0,"note":"Opponens pollicis rotates the first metacarpal to produce opposition; it does not insert on a thumb phalanx.","source":{"volume":6,"pages":[25]},"externalSources":[{"label":"UAMS · Upper limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-upper-limb/"}]},{"id":"l001","muscle":"Sartorius","region":"Hip & thigh","priority":"essential","focus":"name","prompt":"Which muscle runs obliquely from the anterior superior iliac spine to the medial proximal tibia?","options":["Sartorius","Gracilis","Rectus femoris","Adductor longus","Tensor fasciae latae"],"answer":0,"note":"Sartorius crosses the anterior thigh diagonally and joins the pes anserinus on the proximal medial tibia.","source":{"volume":6,"pages":[32]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l002","muscle":"Vastus intermedius","region":"Hip & thigh","priority":"essential","focus":"name","prompt":"Which quadriceps muscle lies directly deep to rectus femoris?","options":["Vastus intermedius","Vastus lateralis","Vastus medialis","Sartorius","Pectineus"],"answer":0,"note":"Vastus intermedius covers the anterior femoral shaft beneath rectus femoris.","source":{"volume":6,"pages":[34,36]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"Texas Tech · Quadriceps dissection","url":"https://anatomy.ttuhscep.edu/schemes/thigh_vid_E720.html"}]},{"id":"l003","muscle":"Gracilis","region":"Hip & thigh","priority":"essential","focus":"name","prompt":"Which superficial, strap-like medial thigh muscle arises from the pubis and reaches the pes anserinus?","options":["Gracilis","Sartorius","Adductor brevis","Pectineus","Semimembranosus"],"answer":0,"note":"Gracilis descends almost vertically along the medial thigh and crosses the knee.","source":{"volume":6,"pages":[39,52]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l004","muscle":"Adductor brevis","region":"Hip & thigh","priority":"important","focus":"name","prompt":"Which short adductor lies deep to both pectineus and adductor longus?","options":["Adductor brevis","Gracilis","Sartorius","Tensor fasciae latae","Rectus femoris"],"answer":0,"note":"Adductor brevis is concealed beneath the more superficial pectineus and adductor longus.","source":{"volume":6,"pages":[39]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l005","muscle":"Gluteus medius","region":"Hip & thigh","priority":"essential","focus":"name","prompt":"Which fan-shaped muscle lies between gluteus maximus and gluteus minimus?","options":["Gluteus medius","Piriformis","Quadratus femoris","Obturator externus","Adductor magnus"],"answer":0,"note":"The principal gluteal layers are maximus, medius, then minimus.","source":{"volume":6,"pages":[43,44]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Gluteal dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/10/PDF-Lab-14.pdf"}]},{"id":"l006","muscle":"Gluteus minimus","region":"Hip & thigh","priority":"essential","focus":"name","prompt":"Which gluteal muscle is exposed by reflecting gluteus medius?","options":["Gluteus minimus","Gluteus maximus","Tensor fasciae latae","Sartorius","Semitendinosus"],"answer":0,"note":"Gluteus minimus is the deepest of the three named gluteal muscles.","source":{"volume":6,"pages":[43,44]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Gluteal dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/10/PDF-Lab-14.pdf"}]},{"id":"l007","muscle":"Piriformis","region":"Hip & thigh","priority":"important","focus":"name","prompt":"Which muscle arises from the anterior sacrum and leaves the pelvis through the greater sciatic foramen?","options":["Piriformis","Obturator internus","Obturator externus","Superior gemellus","Quadratus femoris"],"answer":0,"note":"Piriformis crosses the greater sciatic foramen; obturator internus turns through the lesser sciatic foramen.","source":{"volume":6,"pages":[45]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l008","muscle":"Obturator internus","region":"Hip & thigh","priority":"important","focus":"name","prompt":"Which muscle turns through the lesser sciatic foramen before its tendon is flanked by the gemelli?","options":["Obturator internus","Obturator externus","Piriformis","Gluteus minimus","Adductor brevis"],"answer":0,"note":"The obturator internus tendon lies between superior and inferior gemellus outside the pelvis.","source":{"volume":6,"pages":[45,46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Gluteal dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/10/PDF-Lab-14.pdf"}]},{"id":"l009","muscle":"Superior gemellus","region":"Hip & thigh","priority":"important","focus":"name","prompt":"Which small deep gluteal muscle lies immediately superior to the obturator internus tendon?","options":["Superior gemellus","Inferior gemellus","Quadratus femoris","Obturator externus","Gluteus maximus"],"answer":0,"note":"Superior gemellus lies above the obturator internus tendon and arises from the ischial spine.","source":{"volume":6,"pages":[46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Gluteal dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/10/PDF-Lab-14.pdf"}]},{"id":"l010","muscle":"Inferior gemellus","region":"Hip & thigh","priority":"important","focus":"name","prompt":"Which small muscle lies immediately inferior to the obturator internus tendon and above quadratus femoris?","options":["Inferior gemellus","Superior gemellus","Piriformis","Gluteus medius","Adductor longus"],"answer":0,"note":"Inferior gemellus flanks the lower border of the obturator internus tendon.","source":{"volume":6,"pages":[46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Gluteal dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/10/PDF-Lab-14.pdf"}]},{"id":"l011","muscle":"Quadratus femoris","region":"Hip & thigh","priority":"important","focus":"name","prompt":"Which rectangular deep gluteal muscle runs from the ischial tuberosity toward the intertrochanteric crest?","options":["Quadratus femoris","Quadratus plantae","Piriformis","Superior gemellus","Tensor fasciae latae"],"answer":0,"note":"Quadratus femoris is a short, horizontally oriented lateral rotator below the gemelli.","source":{"volume":6,"pages":[46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Gluteal dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/10/PDF-Lab-14.pdf"}]},{"id":"l012","muscle":"Semitendinosus","region":"Hip & thigh","priority":"essential","focus":"name","prompt":"Which posterior thigh muscle has a long cord-like distal tendon that joins the pes anserinus?","options":["Semitendinosus","Semimembranosus","Biceps femoris long head","Biceps femoris short head","Adductor magnus"],"answer":0,"note":"Semitendinosus reaches the proximal medial tibia as part of the pes anserinus.","source":{"volume":6,"pages":[48,52]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"University of Washington · Semitendinosus","url":"https://rad.uw.edu/muscle-atlas/semitendinosus"}]},{"id":"l013","muscle":"Semimembranosus","region":"Hip & thigh","priority":"essential","focus":"name","prompt":"Which medial hamstring has a broad membranous tendon and inserts on the posterior medial tibial condyle?","options":["Semimembranosus","Semitendinosus","Gracilis","Sartorius","Biceps femoris long head"],"answer":0,"note":"Semimembranosus inserts on the posterior medial tibial condyle, rather than the pes anserinus.","source":{"volume":6,"pages":[48]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"University of Washington · Semimembranosus","url":"https://rad.uw.edu/muscle-atlas/semimembranosus"}]},{"id":"l014","muscle":"Plantaris","region":"Leg & foot","priority":"standard","focus":"name","prompt":"Which calf muscle has a small proximal muscle belly and a remarkably long, slender tendon toward the calcaneus?","options":["Plantaris","Soleus","Gastrocnemius","Popliteus","Tibialis posterior"],"answer":0,"note":"The plantaris tendon is easily mistaken for a nerve during dissection.","source":{"volume":6,"pages":[64,65]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l015","muscle":"Extensor digitorum longus","region":"Leg & foot","priority":"essential","focus":"name","prompt":"Which anterior leg muscle divides into tendons extending toes 2–5?","options":["Extensor digitorum longus","Extensor hallucis longus","Tibialis anterior","Fibularis tertius","Flexor digitorum longus"],"answer":0,"note":"Extensor digitorum longus reaches the four lateral toes; hallucis muscles serve the great toe.","source":{"volume":6,"pages":[57]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l016","muscle":"Fibularis longus","region":"Leg & foot","priority":"essential","focus":"name","prompt":"Which lateral leg muscle passes behind the lateral malleolus, under the cuboid, and across the sole?","options":["Fibularis longus","Fibularis brevis","Fibularis tertius","Tibialis anterior","Extensor digitorum longus"],"answer":0,"note":"Fibularis longus crosses the sole toward the first metatarsal and medial cuneiform.","source":{"volume":6,"pages":[61]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Leg and foot dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/11/PDF-Lab-15.pdf"}]},{"id":"l017","muscle":"Abductor hallucis","region":"Leg & foot","priority":"standard","focus":"name","prompt":"Which first-layer plantar muscle forms the medial border of the sole and moves the great toe away from the second toe?","options":["Abductor hallucis","Adductor hallucis","Flexor digitorum brevis","Abductor digiti minimi","Quadratus plantae"],"answer":0,"note":"Abductor hallucis lies along the medial sole and abducts the great toe.","source":{"volume":6,"pages":[71,72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l018","muscle":"Abductor digiti minimi","region":"Leg & foot","priority":"standard","focus":"name","prompt":"Which superficial plantar muscle forms the lateral border of the sole and abducts the fifth toe?","options":["Abductor digiti minimi","Flexor digiti minimi brevis","Abductor hallucis","Flexor digitorum brevis","Adductor hallucis"],"answer":0,"note":"Abductor digiti minimi is the lateral member of the first plantar muscle layer.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l019","muscle":"Psoas major","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"With the trunk fixed, what is the principal lower-limb action of psoas major?","options":["Flexion of the thigh at the hip","Extension of the leg at the knee","Plantarflexion at the ankle","Extension of the thigh at the hip","Flexion of the leg at the knee"],"answer":0,"note":"Psoas major crosses the anterior hip and is a powerful hip flexor.","source":{"volume":6,"pages":[32]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l020","muscle":"Iliacus","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"With the pelvis fixed, which action does iliacus produce?","options":["Hip flexion","Knee extension","Knee flexion","Ankle dorsiflexion","Great-toe extension"],"answer":0,"note":"Iliacus joins psoas major to form iliopsoas, a major hip-flexor unit.","source":{"volume":6,"pages":[32]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l021","muscle":"Tensor fasciae latae","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which combination describes the hip actions of tensor fasciae latae?","options":["Flexion, abduction, and medial rotation","Extension, adduction, and lateral rotation","Flexion, adduction, and lateral rotation","Extension, abduction, and lateral rotation","Extension, adduction, and medial rotation"],"answer":0,"note":"Tensor fasciae latae flexes, abducts, and medially rotates the thigh while tensing the iliotibial tract.","source":{"volume":6,"pages":[32]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l022","muscle":"Rectus femoris","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which pair of actions is produced by rectus femoris?","options":["Hip flexion and knee extension","Hip extension and knee flexion","Hip flexion and knee flexion","Hip extension and knee extension","Knee flexion and ankle plantarflexion"],"answer":0,"note":"Rectus femoris crosses both the hip and knee; the other three quadriceps muscles do not cross the hip.","source":{"volume":6,"pages":[34]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l023","muscle":"Vastus medialis","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"What is the principal joint movement produced by vastus medialis?","options":["Knee extension","Knee flexion","Hip flexion","Hip adduction","Ankle plantarflexion"],"answer":0,"note":"Vastus medialis extends the knee and contributes to patellar stability.","source":{"volume":6,"pages":[34,36]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l024","muscle":"Adductor magnus: hamstring part","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which hip action is particularly associated with the hamstring part of adductor magnus?","options":["Hip extension","Hip abduction","Knee extension","Knee flexion","Ankle dorsiflexion"],"answer":0,"note":"The hamstring part of adductor magnus extends the thigh at the hip.","source":{"volume":6,"pages":[37,41]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l025","muscle":"Adductor longus","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which is the principal action of adductor longus?","options":["Adduction of the thigh at the hip","Abduction of the thigh at the hip","Extension of the leg at the knee","Flexion of the leg at the knee","Plantarflexion of the foot at the ankle"],"answer":0,"note":"Adductor longus pulls the femur toward the midline.","source":{"volume":6,"pages":[39]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l026","muscle":"Obturator externus","region":"Hip & thigh","priority":"important","focus":"action","prompt":"Which movement is a standard principal action of obturator externus?","options":["Lateral rotation of the thigh at the hip","Medial rotation of the thigh at the hip","Extension of the leg at the knee","Flexion of the leg at the knee","Eversion of the foot"],"answer":0,"note":"Obturator externus laterally rotates the thigh and helps stabilize the femoral head.","source":{"volume":6,"pages":[46]},"correction":{"text":"The notes emphasize adduction; standard anatomy identifies lateral rotation as a principal action.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l027","muscle":"Gluteus maximus","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which major movement does gluteus maximus produce when rising from a chair?","options":["Hip extension","Hip flexion","Ankle dorsiflexion","Toe extension","Knee flexion"],"answer":0,"note":"Gluteus maximus is a powerful hip extensor, especially when extending a flexed hip.","source":{"volume":6,"pages":[43,44]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l028","muscle":"Biceps femoris long head","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which pair of movements can the long head of biceps femoris produce?","options":["Hip extension and knee flexion","Hip flexion and knee extension","Hip flexion and knee flexion","Hip extension and knee extension","Knee extension and ankle plantarflexion"],"answer":0,"note":"The long head crosses both hip and knee, enabling hip extension and knee flexion.","source":{"volume":6,"pages":[49]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"University of Washington · Biceps femoris long head","url":"https://rad.uw.edu/muscle-atlas/biceps-femoris-long-head"}]},{"id":"l029","muscle":"Biceps femoris short head","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which statement correctly describes the short head of biceps femoris?","options":["It flexes the knee but does not directly extend the hip","It extends the knee but does not directly flex the hip","It flexes the hip and extends the knee","It extends the hip and flexes the knee","It plantarflexes the ankle and flexes the knee"],"answer":0,"note":"The short head arises from the femur and does not cross the hip joint.","source":{"volume":6,"pages":[49]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"University of Washington · Biceps femoris short head","url":"https://rad.uw.edu/muscle-atlas/biceps-femoris-short-head"}]},{"id":"l030","muscle":"Tibialis anterior","region":"Leg & foot","priority":"essential","focus":"action","prompt":"Which pair of foot movements does tibialis anterior produce?","options":["Dorsiflexion and inversion","Dorsiflexion and eversion","Plantarflexion and inversion","Plantarflexion and eversion","Great-toe flexion and eversion"],"answer":0,"note":"Its tendon passes anterior to the ankle and reaches the medial foot.","source":{"volume":6,"pages":[56]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l031","muscle":"Fibularis tertius","region":"Leg & foot","priority":"important","focus":"action","prompt":"Which pair describes the actions of fibularis tertius?","options":["Ankle dorsiflexion and foot eversion","Ankle plantarflexion and foot eversion","Ankle dorsiflexion and foot inversion","Ankle plantarflexion and foot inversion","Fifth-toe flexion and foot inversion"],"answer":0,"note":"Fibularis tertius belongs to the anterior leg compartment and inserts on the fifth metatarsal.","source":{"volume":6,"pages":[57]},"correction":{"text":"The notes mention little-toe dorsiflexion; attachment to a metatarsal does not directly extend the toe.","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/11/PDF-Lab-15.pdf"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Leg and foot dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/11/PDF-Lab-15.pdf"}]},{"id":"l032","muscle":"Gastrocnemius","region":"Leg & foot","priority":"essential","focus":"action","prompt":"Which pair of movements can gastrocnemius produce?","options":["Knee flexion and ankle plantarflexion","Knee extension and ankle plantarflexion","Knee flexion and ankle dorsiflexion","Knee extension and ankle dorsiflexion","Hip extension and ankle plantarflexion"],"answer":0,"note":"Gastrocnemius crosses the knee and ankle, unlike soleus, which crosses only the ankle.","source":{"volume":6,"pages":[64]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l033","muscle":"Soleus","region":"Leg & foot","priority":"essential","focus":"action","prompt":"Which movement is the main action of soleus?","options":["Plantarflexion at the ankle","Dorsiflexion at the ankle","Flexion at the knee","Extension at the knee","Extension of the toes"],"answer":0,"note":"Soleus plantarflexes the foot; it does not cross the knee.","source":{"volume":6,"pages":[64]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l034","muscle":"Popliteus","region":"Leg & foot","priority":"important","focus":"action","prompt":"With the foot free to move, how does popliteus help unlock the extended knee?","options":["By medially rotating the tibia on the femur","By laterally rotating the tibia on the femur","By dorsiflexing the ankle","By extending the great toe","By extending the hip"],"answer":0,"note":"Popliteus medially rotates the tibia to initiate knee flexion; with the foot fixed, it laterally rotates the femur.","source":{"volume":6,"pages":[67,68]},"correction":{"text":"Popliteus acts on the knee, not the toes; the toe-dorsiflexion statement on page 67 is incorrect.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l035","muscle":"Flexor hallucis longus","region":"Leg & foot","priority":"important","focus":"action","prompt":"Which toe movement is produced by flexor hallucis longus?","options":["Flexion of the great toe","Extension of the great toe","Abduction of the fifth toe","Extension of toes 2–5","Abduction of toes 2–4"],"answer":0,"note":"Flexor hallucis longus reaches the distal phalanx of the great toe and flexes it.","source":{"volume":6,"pages":[67]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l036","muscle":"First lumbrical of the foot","region":"Leg & foot","priority":"important","focus":"action","prompt":"What is the characteristic joint-action pattern of the first lumbrical of the foot?","options":["Flexion at the second MTP joint and extension at its IP joints","Extension at the second MTP joint and flexion at its IP joints","Extension at both the second MTP and IP joints","Flexion at both the second MTP and IP joints","Flexion of the great toe at its IP joint"],"answer":0,"note":"Foot lumbricals flex metatarsophalangeal joints while extending interphalangeal joints; the first lumbrical serves the second toe.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l037","muscle":"Psoas minor","region":"Hip & thigh","priority":"standard","focus":"origin","prompt":"From which vertebral region does psoas minor arise?","options":["Bodies of T12 and L1 and their intervening disc","Bodies of L4 and L5 and their intervening disc","Anterior surface of the sacrum","Spinous processes of T12 and L1","Transverse processes of C1 and C2"],"answer":0,"note":"Psoas minor arises from T12–L1 and does not extend to the femur.","source":{"volume":6,"pages":[33]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l038","muscle":"Pectineus","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which site is the principal origin of pectineus?","options":["Pecten pubis on the superior pubic ramus","Ischial tuberosity","Anterior inferior iliac spine","Anterior surface of the sacrum","Greater trochanter of the femur"],"answer":0,"note":"Pectineus runs from the pecten pubis to the pectineal line of the femur.","source":{"volume":6,"pages":[39]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l039","muscle":"Vastus lateralis","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which region contributes to the origin of vastus lateralis?","options":["Greater trochanter and lateral lip of the linea aspera","Anterior inferior iliac spine and acetabular rim","Ischial tuberosity and inferior pubic ramus","Medial surface of the proximal tibia","Anterior surface of the sacrum"],"answer":0,"note":"Vastus lateralis arises from the femur, unlike rectus femoris, which arises from the pelvis.","source":{"volume":6,"pages":[34,36]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"University of Washington · Vastus lateralis","url":"https://rad.uw.edu/muscle-atlas/vastus-lateralis"}]},{"id":"l040","muscle":"Adductor magnus: adductor part","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which pelvic region gives origin to the adductor part of adductor magnus?","options":["Ischiopubic ramus","Anterior superior iliac spine","Anterior inferior iliac spine","Anterior surface of the sacrum","Posterior superior iliac spine"],"answer":0,"note":"The adductor part arises from the ischiopubic ramus; the hamstring part arises from the ischial tuberosity.","source":{"volume":6,"pages":[41]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l041","muscle":"Biceps femoris short head","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Where does the short head of biceps femoris arise?","options":["Linea aspera and lateral supracondylar region of the femur","Ischial tuberosity","Anterior inferior iliac spine","Superior pubic ramus","Medial tibial condyle"],"answer":0,"note":"The femoral origin explains why the short head does not cross the hip.","source":{"volume":6,"pages":[49]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l042","muscle":"Gluteus medius","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Between which gluteal lines does gluteus medius mainly arise?","options":["Posterior and anterior gluteal lines","Anterior and inferior gluteal lines","Inferior gluteal line and acetabular margin","Posterior gluteal line and sacral midline","Iliac crest and superior pubic ramus"],"answer":0,"note":"Gluteus medius arises between the posterior and anterior gluteal lines.","source":{"volume":6,"pages":[43,53]},"correction":{"text":"Page 43 repeats the minimus origin for medius; page 53 and standard anatomy give the correct posterior–anterior interval.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l043","muscle":"Gluteus minimus","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Between which gluteal lines does gluteus minimus mainly arise?","options":["Anterior and inferior gluteal lines","Posterior and anterior gluteal lines","Posterior gluteal line and iliac crest","Iliac crest and superior pubic ramus","Sacral midline and posterior gluteal line"],"answer":0,"note":"Gluteus minimus originates inferior to gluteus medius, between the anterior and inferior gluteal lines.","source":{"volume":6,"pages":[43,53]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l044","muscle":"Superior gemellus","region":"Hip & thigh","priority":"important","focus":"origin","prompt":"Which bony landmark gives origin to superior gemellus?","options":["Ischial spine","Ischial tuberosity","Anterior superior iliac spine","Pecten pubis","Lesser trochanter"],"answer":0,"note":"Superior gemellus arises from the ischial spine, above the obturator internus tendon.","source":{"volume":6,"pages":[46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l045","muscle":"Inferior gemellus","region":"Hip & thigh","priority":"important","focus":"origin","prompt":"Which bony landmark gives origin to inferior gemellus?","options":["Upper part of the ischial tuberosity","Ischial spine","Anterior inferior iliac spine","Anterior surface of the sacrum","Pecten pubis"],"answer":0,"note":"Inferior gemellus arises from the upper ischial tuberosity, below the obturator internus tendon.","source":{"volume":6,"pages":[46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l046","muscle":"Extensor hallucis longus","region":"Leg & foot","priority":"essential","focus":"origin","prompt":"Which site contributes to the origin of extensor hallucis longus?","options":["Middle anterior fibula and adjacent interosseous membrane","Posterior tibia below the soleal line","Medial femoral condyle","Plantar surface of the calcaneus","Base of the fifth metatarsal"],"answer":0,"note":"Extensor hallucis longus arises deep in the anterior compartment from the fibula and interosseous membrane.","source":{"volume":6,"pages":[57]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l047","muscle":"Fibularis brevis","region":"Leg & foot","priority":"essential","focus":"origin","prompt":"Which region is the main origin of fibularis brevis?","options":["Distal lateral surface of the fibula","Proximal medial surface of the tibia","Medial femoral condyle","Anterior surface of the patella","Plantar surface of the cuboid"],"answer":0,"note":"Fibularis brevis arises lower on the lateral fibula than fibularis longus.","source":{"volume":6,"pages":[62]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l048","muscle":"Flexor digitorum longus","region":"Leg & foot","priority":"important","focus":"origin","prompt":"Which bone provides the principal origin of flexor digitorum longus?","options":["Posterior surface of the tibia","Anterior surface of the fibula","Anterior surface of the femur","Plantar surface of the calcaneus","Dorsal surface of the navicular"],"answer":0,"note":"Flexor digitorum longus arises from posterior tibia; flexor hallucis longus arises mainly from posterior fibula.","source":{"volume":6,"pages":[67]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l049","muscle":"Flexor hallucis brevis","region":"Leg & foot","priority":"standard","focus":"origin","prompt":"Which pair of tarsal bones contributes to the origin of flexor hallucis brevis?","options":["Cuboid and lateral cuneiform","Talus and calcaneus","Navicular and talus","Calcaneus and intermediate cuneiform","Navicular and medial cuneiform"],"answer":0,"note":"The page 72 table lists the cuboid and lateral cuneiform as origins of flexor hallucis brevis.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l050","muscle":"Adductor hallucis: oblique head","region":"Leg & foot","priority":"standard","focus":"origin","prompt":"Which metatarsal region gives origin to the oblique head of adductor hallucis?","options":["Bases of metatarsals 2–4","Heads of metatarsals 1–2","Base of metatarsal 5 only","Head of metatarsal 1 only","Shaft of metatarsal 1 only"],"answer":0,"note":"The oblique head originates proximally from metatarsal bases; the transverse head arises more distally.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l051","muscle":"Adductor hallucis: transverse head","region":"Leg & foot","priority":"standard","focus":"origin","prompt":"Which structures give origin to the transverse head of adductor hallucis?","options":["Region of the metatarsal heads and plantar MTP ligaments of toes 3–5","Bases of metatarsals 2–4","Medial calcaneal tuberosity","Posterior tibial surface","Dorsal calcaneal surface"],"answer":0,"note":"The transverse head crosses the forefoot near the metatarsal heads.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l052","muscle":"Dorsal interossei of the foot","region":"Leg & foot","priority":"important","focus":"origin","prompt":"What is the characteristic origin pattern of the dorsal interossei of the foot?","options":["Adjacent sides of two metatarsals","Medial side of one metatarsal only","Tendons of flexor digitorum longus","Medial calcaneal tuberosity","Base of the first proximal phalanx"],"answer":0,"note":"Dorsal interossei occupy the spaces between adjacent metatarsals and have a bipennate arrangement.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l053","muscle":"Plantar interossei of the foot","region":"Leg & foot","priority":"important","focus":"origin","prompt":"From which metatarsal surfaces do the three plantar interossei arise?","options":["Medial sides of metatarsals 3–5","Lateral sides of metatarsals 1–3","Adjacent sides of all five metatarsals","Dorsal bases of metatarsals 1–2","Plantar head of metatarsal 1 only"],"answer":0,"note":"Plantar interossei act on toes 3–5, drawing them toward the second-toe axis.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l054","muscle":"Psoas major","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"What is the femoral insertion of psoas major?","options":["Lesser trochanter","Greater trochanter","Gluteal tuberosity","Adductor tubercle","Lateral femoral condyle"],"answer":0,"note":"Psoas major and iliacus share an insertion at the lesser trochanter.","source":{"volume":6,"pages":[32]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l055","muscle":"Iliacus","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Iliacus joins psoas major to insert at which landmark?","options":["Lesser trochanter of the femur","Greater trochanter of the femur","Tibial tuberosity","Fibular head","Adductor tubercle"],"answer":0,"note":"The common iliopsoas tendon reaches the lesser trochanter.","source":{"volume":6,"pages":[32]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l056","muscle":"Vastus medialis","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Through the quadriceps tendon, patella, and patellar ligament, vastus medialis ultimately transmits force to which landmark?","options":["Tibial tuberosity","Fibular head","Medial tibial condyle posteriorly","Lesser trochanter","Adductor tubercle"],"answer":0,"note":"All four quadriceps muscles transmit force through the patella and patellar ligament to the tibial tuberosity.","source":{"volume":6,"pages":[34]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l057","muscle":"Articularis genu","region":"Hip & thigh","priority":"standard","focus":"insertion","prompt":"Articularis genu attaches distally to which structure?","options":["Articular capsule of the knee","Fibular head","Pes anserinus","Achilles tendon","Lesser trochanter"],"answer":0,"note":"Articularis genu elevates the knee-joint capsule during knee extension.","source":{"volume":6,"pages":[52]},"correction":{"text":"Page 52 labels articularis genu in the attachment figure; its capsular insertion is clarified by the official anatomy table.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l058","muscle":"Adductor magnus: hamstring part","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"What is the distinctive insertion of the hamstring part of adductor magnus?","options":["Adductor tubercle of the femur","Lesser trochanter","Tibial tuberosity","Fibular head","Anterior superior iliac spine"],"answer":0,"note":"The hamstring part ends at the adductor tubercle, while the adductor part has a broad femoral insertion.","source":{"volume":6,"pages":[41]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l059","muscle":"Semimembranosus","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Where does semimembranosus primarily insert?","options":["Posterior surface of the medial tibial condyle","Fibular head","Tibial tuberosity","Anterior surface of the patella","Lateral femoral epicondyle"],"answer":0,"note":"Semimembranosus inserts posteriorly on the medial tibial condyle; semitendinosus joins the pes anserinus.","source":{"volume":6,"pages":[48]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"University of Washington · Semimembranosus","url":"https://rad.uw.edu/muscle-atlas/semimembranosus"}]},{"id":"l060","muscle":"Biceps femoris long head","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Which landmark receives the principal distal insertion of the long head of biceps femoris?","options":["Head of the fibula","Medial proximal tibia at the pes anserinus","Posterior medial tibial condyle","Tibial tuberosity","Calcaneal tuberosity"],"answer":0,"note":"Biceps femoris reaches the fibular head on the lateral side of the knee.","source":{"volume":6,"pages":[49]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l061","muscle":"Tibialis anterior","region":"Leg & foot","priority":"essential","focus":"insertion","prompt":"Which pair receives the insertion of tibialis anterior?","options":["Medial cuneiform and base of metatarsal 1","Navicular tuberosity and base of metatarsal 5","Cuboid and base of metatarsal 5","Talus and calcaneus","Distal phalanges of toes 2–5"],"answer":0,"note":"Tibialis anterior reaches the medial foot after passing in front of the ankle.","source":{"volume":6,"pages":[56]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l062","muscle":"Tibialis posterior","region":"Leg & foot","priority":"essential","focus":"insertion","prompt":"Which prominent medial-foot landmark is a major insertion of tibialis posterior?","options":["Navicular tuberosity","Tuberosity of metatarsal 5","Dorsal distal phalanx of the great toe","Posterior calcaneal tuberosity","Lateral malleolus"],"answer":0,"note":"Tibialis posterior has a broad insertion, with a major attachment to the navicular tuberosity.","source":{"volume":6,"pages":[66]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l063","muscle":"Fibularis brevis","region":"Leg & foot","priority":"essential","focus":"insertion","prompt":"Where does fibularis brevis insert?","options":["Tuberosity at the base of metatarsal 5","Base of metatarsal 1","Navicular tuberosity","Distal phalanx of toe 5","Posterior calcaneal tuberosity"],"answer":0,"note":"Fibularis brevis ends at the fifth metatarsal base after passing behind the lateral malleolus.","source":{"volume":6,"pages":[62]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l064","muscle":"Flexor digitorum longus","region":"Leg & foot","priority":"important","focus":"insertion","prompt":"Where do the four terminal tendons of flexor digitorum longus insert?","options":["Bases of the distal phalanges of toes 2–5","Bases of the middle phalanges of toes 2–5","Bases of the proximal phalanges of toes 2–5","Bases of metatarsals 2–5","Extensor expansions of toes 2–5"],"answer":0,"note":"Flexor digitorum longus reaches distal phalanges; flexor digitorum brevis reaches middle phalanges.","source":{"volume":6,"pages":[67]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l065","muscle":"Extensor hallucis brevis","region":"Leg & foot","priority":"standard","focus":"insertion","prompt":"Where does extensor hallucis brevis insert?","options":["Dorsal base of the proximal phalanx of the great toe","Dorsal base of the distal phalanx of the great toe","Plantar base of the distal phalanx of the great toe","Base of metatarsal 1","Navicular tuberosity"],"answer":0,"note":"The short extensor reaches the proximal phalanx; extensor hallucis longus reaches the distal phalanx.","source":{"volume":6,"pages":[71]},"correction":{"text":"The page 71 figure labels extensor hallucis brevis; the official table clarifies its proximal-phalangeal insertion.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l066","muscle":"Extensor digitorum brevis","region":"Leg & foot","priority":"important","focus":"insertion","prompt":"Excluding the separately named extensor hallucis brevis, where do extensor digitorum brevis tendons typically join?","options":["Extensor tendons or expansions of toes 2–4","Extensor expansions of toes 3–5","Plantar bases of distal phalanges 2–5","Base of metatarsal 5","Plantar base of the great-toe proximal phalanx"],"answer":0,"note":"Extensor digitorum brevis supplies toes 2–4; its great-toe component is named extensor hallucis brevis.","source":{"volume":6,"pages":[71]},"correction":{"text":"The notes give an imprecise toe range. Separate EDB to toes 2–4 from EHB to the great toe.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l067","muscle":"Flexor digitorum brevis","region":"Leg & foot","priority":"standard","focus":"insertion","prompt":"Where do flexor digitorum brevis tendons typically insert?","options":["Middle phalanges of toes 2–5","Distal phalanges of toes 2–5","Proximal phalanges of toes 2–5","Bases of metatarsals 2–5","Distal phalanx of the great toe"],"answer":0,"note":"Its split tendons reach middle phalanges and allow the long flexor tendons to pass through.","source":{"volume":6,"pages":[72]},"correction":{"text":"The page 72 table appears to print toes II–IV; the standard attachment is to the middle phalanges of toes 2–5.","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l068","muscle":"Quadratus plantae","region":"Leg & foot","priority":"standard","focus":"insertion","prompt":"Quadratus plantae inserts into which structure?","options":["Tendon of flexor digitorum longus","Tendon of flexor hallucis longus","Tendon of tibialis anterior","Base of metatarsal 1","Dorsal extensor expansion of the great toe"],"answer":0,"note":"Quadratus plantae acts through the long toe-flexor tendon rather than attaching directly to a toe bone.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l069","muscle":"Lumbricals 2–4 of the foot","region":"Leg & foot","priority":"important","focus":"insertion","prompt":"Where do the second through fourth lumbricals of the foot insert?","options":["Medial extensor expansions of toes 3–5","Lateral extensor expansions of toes 3–5","Plantar distal phalanges of toes 3–5","Bases of metatarsals 3–5","Medial extensor expansion of the great toe"],"answer":0,"note":"Each lumbrical passes to the medial extensor expansion of its corresponding toe.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l070","muscle":"Flexor digiti minimi brevis","region":"Leg & foot","priority":"standard","focus":"insertion","prompt":"Where does flexor digiti minimi brevis of the foot insert?","options":["Base of the proximal phalanx of toe 5","Base of the middle phalanx of toe 5","Base of the distal phalanx of toe 5","Base of metatarsal 5","Base of the proximal phalanx of toe 1"],"answer":0,"note":"Flexor digiti minimi brevis crosses the fifth MTP joint to reach the fifth proximal phalanx.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l071","muscle":"Sartorius","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which combination can sartorius produce?","options":["Hip flexion, abduction, lateral rotation, and knee flexion","Hip extension, adduction, medial rotation, and knee extension","Hip flexion, adduction, medial rotation, and knee extension","Hip extension, abduction, lateral rotation, and knee extension","Hip flexion, abduction, medial rotation, and knee extension"],"answer":0,"note":"Sartorius contributes to the crossed-leg position through its combined hip actions and knee flexion.","source":{"volume":6,"pages":[32,36]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l072","muscle":"Tensor fasciae latae","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Tensor fasciae latae inserts into which fascial structure?","options":["Iliotibial tract","Pes anserinus","Quadriceps tendon","Plantar aponeurosis","Obturator membrane"],"answer":0,"note":"Tensor fasciae latae joins the iliotibial tract, which continues toward the lateral proximal tibia.","source":{"volume":6,"pages":[32]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l073","muscle":"Rectus femoris","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which landmark gives origin to the straight head of rectus femoris?","options":["Anterior inferior iliac spine","Anterior superior iliac spine","Posterior superior iliac spine","Ischial spine","Ischial tuberosity"],"answer":0,"note":"The straight head originates at the AIIS; the reflected head originates above the acetabulum.","source":{"volume":6,"pages":[34,36]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l074","muscle":"Iliacus","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which region of the ilium is the broad principal origin of iliacus?","options":["Iliac fossa","External surface between anterior and posterior gluteal lines","External surface between anterior and inferior gluteal lines","Posterior surface behind the posterior gluteal line","Anterior inferior iliac spine alone"],"answer":0,"note":"Iliacus spreads across the internal iliac fossa before joining the iliopsoas tendon.","source":{"volume":6,"pages":[32,36]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l075","muscle":"Psoas major","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which structures provide the principal vertebral origins of psoas major?","options":["Lumbar vertebral bodies and transverse processes","Lumbar spinous processes and supraspinous ligament","Posterior sacral foramina and median sacral crest","Cervical vertebral bodies and transverse processes","Thoracic spinous processes T1–T6"],"answer":0,"note":"Psoas major originates beside the lumbar spine rather than from its posterior spinous processes.","source":{"volume":6,"pages":[32,36]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l076","muscle":"Adductor longus","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Where does adductor longus attach on the femur?","options":["Middle part of the linea aspera","Lesser trochanter","Greater trochanter","Intertrochanteric crest at the quadrate tubercle","Adductor tubercle alone"],"answer":0,"note":"Adductor longus reaches the middle linea aspera; the adductor tubercle is characteristic of the hamstring part of adductor magnus.","source":{"volume":6,"pages":[39]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l077","muscle":"Adductor brevis","region":"Hip & thigh","priority":"important","focus":"origin","prompt":"Which pelvic site gives origin to adductor brevis?","options":["Body and inferior ramus of the pubis","Anterior superior iliac spine","Anterior inferior iliac spine","Posterior surface of the sacrum","Superior border of the acetabulum"],"answer":0,"note":"Adductor brevis begins at the pubis and passes to the proximal femoral linea aspera and pectineal line.","source":{"volume":6,"pages":[39,41]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l078","muscle":"Gracilis","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which pair of joint movements can gracilis produce?","options":["Hip adduction and knee flexion","Hip abduction and knee extension","Hip adduction and knee extension","Hip extension and ankle dorsiflexion","Hip abduction and ankle plantarflexion"],"answer":0,"note":"Unlike most medial thigh adductors, gracilis crosses the knee and can flex it.","source":{"volume":6,"pages":[39,41]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l079","muscle":"Obturator externus","region":"Hip & thigh","priority":"important","focus":"insertion","prompt":"Where does the tendon of obturator externus insert?","options":["Trochanteric fossa of the femur","Lesser trochanter","Adductor tubercle","Gluteal tuberosity","Anterior inferior iliac spine"],"answer":0,"note":"Its tendon passes below and behind the femoral neck to the trochanteric fossa.","source":{"volume":6,"pages":[46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l080","muscle":"Gluteus maximus","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Which pair describes the principal insertions of gluteus maximus?","options":["Iliotibial tract and gluteal tuberosity","Greater trochanter and lesser trochanter","Linea aspera and adductor tubercle","Medial tibial condyle and fibular head","Pectineal line and intertrochanteric crest"],"answer":0,"note":"Gluteus maximus inserts mainly into the iliotibial tract, with deeper lower fibers reaching the gluteal tuberosity.","source":{"volume":6,"pages":[43]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l081","muscle":"Gluteus medius","region":"Hip & thigh","priority":"essential","focus":"insertion","prompt":"Which femoral landmark receives the insertion of gluteus medius?","options":["Greater trochanter","Lesser trochanter","Adductor tubercle","Medial epicondyle","Intercondylar fossa"],"answer":0,"note":"Gluteus medius reaches the greater trochanter; it does not share the iliopsoas insertion at the lesser trochanter.","source":{"volume":6,"pages":[43]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l082","muscle":"Gluteus minimus","region":"Hip & thigh","priority":"essential","focus":"action","prompt":"Which pair of hip movements is associated with gluteus minimus?","options":["Abduction and medial rotation","Adduction and lateral rotation","Adduction and knee extension","Hip extension and ankle plantarflexion","Hip flexion and knee flexion"],"answer":0,"note":"Gluteus minimus abducts and medially rotates the thigh, also helping stabilize the pelvis.","source":{"volume":6,"pages":[43,44]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l083","muscle":"Piriformis","region":"Hip & thigh","priority":"important","focus":"insertion","prompt":"After passing through the greater sciatic foramen, piriformis inserts on which landmark?","options":["Superior border of the greater trochanter","Lesser trochanter","Adductor tubercle","Medial femoral condyle","Tibial tuberosity"],"answer":0,"note":"Piriformis crosses from the anterior sacrum to the superior part of the greater trochanter.","source":{"volume":6,"pages":[45]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l084","muscle":"Quadratus femoris","region":"Hip & thigh","priority":"important","focus":"action","prompt":"Which is the principal hip movement produced by quadratus femoris?","options":["Lateral rotation of the thigh","Medial rotation of the thigh","Flexion of the knee","Extension of the knee","Dorsiflexion of the ankle"],"answer":0,"note":"Quadratus femoris is one of the short external rotators of the hip.","source":{"volume":6,"pages":[46]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l085","muscle":"Semitendinosus","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which bony landmark gives origin to semitendinosus?","options":["Ischial tuberosity","Anterior superior iliac spine","Inferior pubic ramus","Lateral lip of the linea aspera","Medial femoral condyle"],"answer":0,"note":"Semitendinosus originates from the ischial tuberosity and crosses both hip and knee.","source":{"volume":6,"pages":[48]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l086","muscle":"Biceps femoris long head","region":"Hip & thigh","priority":"essential","focus":"origin","prompt":"Which site distinguishes the origin of the long head of biceps femoris from that of its short head?","options":["Ischial tuberosity","Lateral lip of the linea aspera","Anterior inferior iliac spine","Superior pubic ramus","Soleal line of the tibia"],"answer":0,"note":"The long head begins on the pelvis; the short head begins on the femur.","source":{"volume":6,"pages":[49]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l087","muscle":"Gastrocnemius: medial head","region":"Leg & foot","priority":"essential","focus":"origin","prompt":"Where does the medial head of gastrocnemius arise?","options":["Femur just superior to the medial condyle","Femur just superior to the lateral condyle","Posterior surface of the fibular head","Soleal line of the tibia","Medial calcaneal tuberosity"],"answer":0,"note":"The two gastrocnemius heads originate from opposite sides of the distal femur, allowing the muscle to cross the knee.","source":{"volume":6,"pages":[64]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l088","muscle":"Soleus","region":"Leg & foot","priority":"essential","focus":"origin","prompt":"Which pair contributes to the origin of soleus?","options":["Soleal line of the tibia and proximal posterior fibula","Medial and lateral femoral condyles","Anterior tibial surface and anterior fibular surface","Medial malleolus and lateral malleolus","Calcaneal tuberosity and plantar aponeurosis"],"answer":0,"note":"Soleus arises below the knee from the tibia and fibula.","source":{"volume":6,"pages":[64,68]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l089","muscle":"Soleus","region":"Leg & foot","priority":"essential","focus":"insertion","prompt":"Through the calcaneal tendon, soleus inserts into which bone?","options":["Calcaneus","Talus","Navicular","Cuboid","First metatarsal"],"answer":0,"note":"The soleus and gastrocnemius share the Achilles tendon attachment to the posterior calcaneus.","source":{"volume":6,"pages":[64]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l090","muscle":"Tibialis posterior","region":"Leg & foot","priority":"essential","focus":"action","prompt":"Which pair of movements does tibialis posterior produce?","options":["Plantarflexion and inversion","Dorsiflexion and inversion","Plantarflexion and eversion","Dorsiflexion and eversion","Toe extension and eversion"],"answer":0,"note":"Tibialis posterior and tibialis anterior both invert the foot, but act oppositely at the ankle.","source":{"volume":6,"pages":[66]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l091","muscle":"Extensor hallucis longus","region":"Leg & foot","priority":"essential","focus":"insertion","prompt":"Where does extensor hallucis longus insert?","options":["Dorsal base of the distal phalanx of the great toe","Dorsal base of the proximal phalanx of the great toe","Plantar base of the distal phalanx of the great toe","Base of the first metatarsal","Navicular tuberosity"],"answer":0,"note":"The long extensor reaches the distal phalanx; the short extensor reaches the proximal phalanx.","source":{"volume":6,"pages":[57]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l092","muscle":"Flexor hallucis longus","region":"Leg & foot","priority":"important","focus":"origin","prompt":"Which region provides the main origin of flexor hallucis longus?","options":["Distal posterior fibula and adjacent interosseous membrane","Middle posterior tibia","Anterior surface of the fibula","Medial femoral condyle","Plantar surface of the cuboid"],"answer":0,"note":"The great-toe long flexor originates largely on the posterior fibula, despite its tendon eventually reaching the medial foot.","source":{"volume":6,"pages":[67]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l093","muscle":"Fibularis longus","region":"Leg & foot","priority":"essential","focus":"insertion","prompt":"After crossing the sole, fibularis longus inserts on which pair?","options":["Medial cuneiform and base of the first metatarsal","Cuboid and base of the fifth metatarsal","Navicular and base of the third metatarsal","Talus and posterior calcaneus","Distal phalanges of toes 2–5"],"answer":0,"note":"Fibularis longus reaches the medial foot; fibularis brevis ends laterally at the fifth metatarsal base.","source":{"volume":6,"pages":[61,62]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"},{"label":"WSU · Leg and foot dissection","url":"https://learning.medicine.wsu.edu/wp-content/uploads/sites/4/2022/11/PDF-Lab-15.pdf"}]},{"id":"l094","muscle":"Fibularis brevis","region":"Leg & foot","priority":"essential","focus":"action","prompt":"Which pair describes the actions of fibularis brevis?","options":["Foot eversion and ankle plantarflexion","Foot inversion and ankle plantarflexion","Foot eversion and ankle dorsiflexion","Foot inversion and ankle dorsiflexion","Great-toe extension and ankle dorsiflexion"],"answer":0,"note":"Its tendon passes behind the ankle axis and reaches the lateral foot.","source":{"volume":6,"pages":[62]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l095","muscle":"Flexor digitorum longus","region":"Leg & foot","priority":"important","focus":"action","prompt":"Which toe joints can flexor digitorum longus directly flex?","options":["MTP, PIP, and DIP joints of toes 2–5","MTP and PIP joints only, without DIP flexion","MTP joints only, with IP extension","Great-toe MTP and IP joints only","MTP joints of toes 2–5, with both IP joints extended"],"answer":0,"note":"Attachment to distal phalanges allows the long flexor to flex all three joints of the lateral four toes.","source":{"volume":6,"pages":[67,68]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l096","muscle":"Flexor hallucis brevis","region":"Leg & foot","priority":"standard","focus":"action","prompt":"Which great-toe movement is directly produced by flexor hallucis brevis?","options":["Flexion at the metatarsophalangeal joint","Flexion at the interphalangeal joint alone","Extension at the metatarsophalangeal joint","Extension at the interphalangeal joint alone","Abduction away from the second toe as its primary action"],"answer":0,"note":"Flexor hallucis brevis inserts on the proximal phalanx and flexes the great-toe MTP joint.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l097","muscle":"Adductor hallucis","region":"Leg & foot","priority":"standard","focus":"action","prompt":"In which direction does adductor hallucis move the great toe?","options":["Toward the second toe","Away from the second toe","Upward at the ankle","Into extension at its IP joint","Toward the medial border of the foot"],"answer":0,"note":"Toe adduction is defined toward the second-toe axis, rather than toward the body midline.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l098","muscle":"Dorsal interossei of the foot","region":"Leg & foot","priority":"important","focus":"action","prompt":"Which toe movement is characteristic of the four dorsal interossei?","options":["Abduction of toes 2–4 away from the second-toe axis","Adduction of toes 3–5 toward the second-toe axis","Abduction of the great toe only","Flexion of the great toe at its IP joint","Plantarflexion at the ankle"],"answer":0,"note":"DAB: dorsal interossei abduct. The second toe can move to either side of its own axis.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l099","muscle":"Plantar interossei of the foot","region":"Leg & foot","priority":"important","focus":"action","prompt":"Which toe movement is characteristic of the three plantar interossei?","options":["Adduction of toes 3–5 toward the second-toe axis","Abduction of toes 2–4 away from the second-toe axis","Extension of the great toe","Abduction of the fifth toe away from the second toe","Dorsiflexion at the ankle"],"answer":0,"note":"PAD: plantar interossei adduct toes 3–5 toward the second toe.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]},{"id":"l100","muscle":"Quadratus plantae","region":"Leg & foot","priority":"standard","focus":"action","prompt":"How does quadratus plantae assist flexor digitorum longus?","options":["It helps align the oblique pull of the long flexor with the toes","It converts toe flexion into toe extension","It abducts the great toe through the long flexor tendon","It directly dorsiflexes the ankle","It extends the knee through the calcaneal tendon"],"answer":0,"note":"Quadratus plantae attaches to the long flexor tendon and improves the direction of its toe-flexing pull.","source":{"volume":6,"pages":[72]},"externalSources":[{"label":"UAMS · Lower limb","url":"https://medicine.uams.edu/neuroscience/education/medical-school-courses/human-structure-module/anatomy-tables/muscle-tables/muscles-of-the-lower-limb/"}]}];
